use std::collections::BTreeMap;

#[derive(Debug, Clone)]
pub struct Xml {
    pub name: String,
    pub attrs: BTreeMap<String, String>,
    pub children: Vec<Xml>,
    pub text: String,
    pub line: usize,
    pub col: usize,
}
impl Xml {
    pub fn child(&self, n: &str) -> Option<&Xml> { self.children.iter().find(|c| c.name == n) }
    pub fn children_named<'a>(&'a self, n: &'a str) -> impl Iterator<Item=&'a Xml> + 'a { self.children.iter().filter(move |c| c.name == n) }
    pub fn text_trim(&self) -> String { self.text.trim().to_string() }
    pub fn child_text(&self, n: &str) -> Option<String> { self.child(n).map(|c| c.text_trim()) }
    pub fn attr(&self, n: &str) -> Option<String> { self.attrs.get(n).cloned() }
}

pub struct Parser<'a> { b: &'a [u8], pos: usize }
pub fn parse_xml(input: &str) -> Result<Xml, String> {
    let mut p = Parser{b: input.as_bytes(), pos:0};
    p.parse_doc()
}
fn line_col(b:&[u8], pos:usize)->(usize,usize){
    let mut line=1usize; let mut last=0usize;
    for i in 0..pos.min(b.len()) { if b[i]==b'\n' { line+=1; last=i+1; } }
    (line, pos-last+1)
}
impl<'a> Parser<'a> {
    fn starts(&self, s:&str)->bool{ self.b[self.pos..].starts_with(s.as_bytes()) }
    fn parse_doc(&mut self)->Result<Xml,String>{
        // skip bom
        if self.b.starts_with(&[0xEF,0xBB,0xBF]) { self.pos=3; }
        loop {
            self.skip_ws();
            if self.pos>=self.b.len() { return Err("the document does not have a root node".into()); }
            if self.starts("<?") { self.skip_until("?>")?; continue; }
            if self.starts("<!--") { self.skip_until("-->")?; continue; }
            if self.starts("<!") { // doctype
                // skip to > respecting brackets
                let start=self.pos; while self.pos<self.b.len() && self.b[self.pos]!=b'>' { self.pos+=1; } if self.pos>=self.b.len(){ return Err("unknown token at 1:1".into()); } self.pos+=1; let _=start; continue; }
            break;
        }
        if self.pos>=self.b.len() { return Err("the document does not have a root node".into()); }
        if self.b[self.pos]!=b'<' { let (l,c)=line_col(self.b,self.pos); return Err(format!("unknown token at {}:{}",l,c)); }
        let root=self.parse_elem()?;
        Ok(root)
    }
    fn skip_ws(&mut self){ while self.pos<self.b.len() && matches!(self.b[self.pos], b' '|b'\n'|b'\r'|b'\t'){ self.pos+=1; } }
    fn skip_until(&mut self, end:&str)->Result<(),String>{ if let Some(idx)=find_sub(&self.b[self.pos..], end.as_bytes()){ self.pos+=idx+end.len(); Ok(()) } else { Err("the root node was opened but never closed".into()) } }
    fn parse_elem(&mut self)->Result<Xml,String>{
        let start=self.pos; let (line,col)=line_col(self.b,start);
        // assume '<'
        self.pos+=1;
        if self.pos>=self.b.len(){ return Err("the root node was opened but never closed".into()); }
        if !is_name_start(self.b[self.pos]) { let (l,c)=line_col(self.b,start); return Err(format!("unknown token at {}:{}",l,c)); }
        let name=self.parse_name()?;
        let mut attrs=BTreeMap::new();
        loop {
            self.skip_ws();
            if self.pos>=self.b.len(){ return Err("the root node was opened but never closed".into()); }
            if self.starts("/>"){ self.pos+=2; return Ok(Xml{name,attrs,children:vec![],text:String::new(),line,col}); }
            if self.b[self.pos]==b'>' { self.pos+=1; break; }
            // attr
            let aname=self.parse_name()?;
            self.skip_ws();
            let mut aval=String::new();
            if self.pos<self.b.len() && self.b[self.pos]==b'=' { self.pos+=1; self.skip_ws(); if self.pos<self.b.len() && (self.b[self.pos]==b'"'||self.b[self.pos]==b'\''){ let q=self.b[self.pos]; self.pos+=1; let s=self.pos; while self.pos<self.b.len() && self.b[self.pos]!=q { self.pos+=1; } aval=decode_entities(&String::from_utf8_lossy(&self.b[s..self.pos]).to_string()); if self.pos<self.b.len(){ self.pos+=1; } } }
            attrs.insert(aname, aval);
        }
        let mut children=Vec::new(); let mut text=String::new();
        loop {
            if self.pos>=self.b.len(){ return Err("the root node was opened but never closed".into()); }
            if self.starts("</") {
                self.pos+=2; let _ename=self.parse_name()?; self.skip_ws(); if self.pos<self.b.len() && self.b[self.pos]==b'>'{ self.pos+=1; }
                return Ok(Xml{name,attrs,children,text,line,col});
            } else if self.starts("<!--") { self.skip_until("-->")?; }
            else if self.starts("<![CDATA[") { self.pos+=9; if let Some(idx)=find_sub(&self.b[self.pos..], b"]]>"){ text.push_str(&String::from_utf8_lossy(&self.b[self.pos..self.pos+idx])); self.pos+=idx+3; } else { return Err("the root node was opened but never closed".into()); } }
            else if self.starts("<?") { self.skip_until("?>")?; }
            else if self.starts("<!") { while self.pos<self.b.len() && self.b[self.pos]!=b'>'{ self.pos+=1; } if self.pos<self.b.len(){self.pos+=1;} }
            else if self.b[self.pos]==b'<' { children.push(self.parse_elem()?); }
            else { let s=self.pos; while self.pos<self.b.len() && self.b[self.pos]!=b'<' { self.pos+=1; } text.push_str(&decode_entities(&String::from_utf8_lossy(&self.b[s..self.pos]))); }
        }
    }
    fn parse_name(&mut self)->Result<String,String>{
        let s=self.pos; while self.pos<self.b.len() && is_name_char(self.b[self.pos]) { self.pos+=1; }
        if s==self.pos { let (l,c)=line_col(self.b,self.pos); return Err(format!("unknown token at {}:{}",l,c)); }
        Ok(String::from_utf8_lossy(&self.b[s..self.pos]).to_string())
    }
}
fn is_name_start(c:u8)->bool{ c.is_ascii_alphabetic() || c==b'_' || c>=0x80 }
fn is_name_char(c:u8)->bool{ c.is_ascii_alphanumeric() || matches!(c,b'_'|b'-'|b'.'|b':') || c>=0x80 }
fn find_sub(h:&[u8], n:&[u8])->Option<usize>{ h.windows(n.len()).position(|w| w==n) }
pub fn decode_entities(s:&str)->String{
    let mut out=String::new(); let mut chars=s.chars().peekable();
    while let Some(c)=chars.next(){
        if c=='&' {
            let mut ent=String::new(); let mut ok=false;
            for c2 in chars.by_ref(){ if c2==';'{ ok=true; break; } ent.push(c2); if ent.len()>10{break;} }
            if ok {
                match ent.as_str(){
                    "lt"=>out.push('<'), "gt"=>out.push('>'), "amp"=>out.push('&'), "apos"=>out.push('\''), "quot"=>out.push('"'),
                    _ if ent.starts_with("#x") || ent.starts_with("#X") => { if let Ok(v)=u32::from_str_radix(&ent[2..],16){ if let Some(ch)=char::from_u32(v){ out.push(ch); } } },
                    _ if ent.starts_with('#') => { if let Ok(v)=ent[1..].parse::<u32>(){ if let Some(ch)=char::from_u32(v){ out.push(ch); } } },
                    _=>{ out.push('&'); out.push_str(&ent); out.push(';'); }
                }
            } else { out.push('&'); out.push_str(&ent); }
        } else { out.push(c); }
    }
    out
}
