            if let Some(v)=e.child_text("resetValue"){ p.reset_value=parse_int(&v).ok(); }
            if let Some(v)=e.child_text("resetMask"){ p.reset_mask=parse_int(&v).ok(); }
        };
        parse_from(x,&mut p);
        if let Some(pr)=x.child("properties"){ parse_from(pr,&mut p); }
        p
    }
    pub fn merge_over(&self, parent:&Props)->Props{ // self overrides parent
        Props{ size:self.size.or(parent.size), access:self.access.or(parent.access), reset_value:self.reset_value.or(parent.reset_value), reset_mask:self.reset_mask.or(parent.reset_mask) }
    }
}
pub fn parse_int(s:&str)->Result<u64,String>{
    let t=s.trim().replace('_', "");
    if let Some(b)=t.strip_prefix('#'){
        // binary with x/don't care
        let clean: String=b.chars().map(|c| if c=='0'||c=='1'{c}else{'0'}).collect();
        return u64::from_str_radix(&clean,2).map_err(|e| e.to_string());
    }
    // scaled suffix K M G
    let (num, mult) = if let Some(stripped)=t.strip_suffix('K'){ (stripped.to_string(),1024u64)} else if let Some(stripped)=t.strip_suffix('M'){ (stripped.to_string(),1024*1024)} else if let Some(stripped)=t.strip_suffix('G'){ (stripped.to_string(),1024*1024*1024)} else { (t.clone(),1)};
    let v=if let Some(h)=num.strip_prefix("0x").or_else(|| num.strip_prefix("0X")){ u64::from_str_radix(h,16) } else if let Some(b)=num.strip_prefix("0b").or_else(|| num.strip_prefix("0B")){ u64::from_str_radix(&b.replace('x',"0").replace('z',"0"),2) } else if let Some(o)=num.strip_prefix("0o"){ u64::from_str_radix(o,8)} else { num.parse::<u64>() };
    v.map(|v| v*mult).map_err(|e| "invalid digit found in string".to_string().replace("invalid digit found in string", &e.to_string()))
}
pub fn parse_bool(s:&str)->bool{ matches!(s.trim(), "true"|"1") }

#[derive(Debug, Clone, Default)]
pub struct Dim { pub dim: u32, pub increment: u64, pub index: Option<String>, pub name_index: Option<String> }

#[derive(Debug, Clone)]
pub struct EnumValue { pub name:String, pub description:Option<String>, pub value:u64, pub is_default:bool }
