}
#[derive(Debug, Clone)]
pub enum BlockElem { Register(Register), Cluster(Cluster) }
impl BlockElem {
    pub fn name(&self)->&str{ match self{ Self::Register(r)=>&r.name, Self::Cluster(c)=>&c.name } }
    pub fn offset(&self)->u64{ match self{ Self::Register(r)=>r.address_offset, Self::Cluster(c)=>c.address_offset } }
    pub fn dim(&self)->Option<&Dim>{ match self{ Self::Register(r)=>&r.dim, Self::Cluster(c)=>&c.dim }.as_ref() }
    pub fn description(&self)->Option<String>{ match self{ Self::Register(r)=>r.description.clone(), Self::Cluster(c)=>c.description.clone() } }
}
#[derive(Debug, Clone)]
pub struct Interrupt { pub name:String, pub description:Option<String>, pub value:u64 }
#[derive(Debug, Clone)]
pub struct Peripheral {
