    pub interrupts:Vec<Interrupt>, pub registers:Vec<BlockElem>, pub derived_from:Option<String>, pub dim:Option<Dim>,
    pub props:Props, pub header_struct_name:Option<String>, pub alternate_peripheral:Option<String>,
}
#[derive(Debug, Clone)]
