}

fn get_dim(x:&Xml)->Option<Dim>{
    let d=x.child_text("dim")?; let dim=d.parse::<u32>().unwrap_or(0);
    let increment=x.child_text("dimIncrement").and_then(|v| parse_int(&v).ok()).unwrap_or(0);
    Some(Dim{dim, increment, index:x.child_text("dimIndex"), name_index:x.child_text("dimNameIndex")})
}
fn parse_enums(x:&Xml)->Vec<EnumSet>{
    let mut out=vec![];
    for e in x.children_named("enumeratedValues"){
        let usage=e.child_text("usage").unwrap_or_else(|| "read-write".into());
        let mut vals=vec![];
        for v in e.children_named("enumeratedValue"){
            vals.push(EnumValue{ name:v.child_text("name").unwrap_or_default(), description:v.child_text("description"), value:v.child_text("value").and_then(|s| parse_int(&s).ok()).unwrap_or(0), is_default:v.child_text("isDefault").map(|s| parse_bool(&s)).unwrap_or(false)});
        }
        out.push(EnumSet{name:e.child_text("name"), description:e.child_text("description"), usage, values:vals, derived_from:e.attr("derivedFrom"), header_enum_name:e.child_text("headerEnumName")});
    }
    out
}
pub fn parse_field(x:&Xml)->Field{
    let (mut off, mut wid)=(0u32,1u32);
    if let Some(v)=x.child_text("bitOffset"){ off=v.parse().unwrap_or(0); }
    if let Some(v)=x.child_text("bitWidth"){ wid=v.parse().unwrap_or(1); }
    if let Some(br)=x.child_text("bitRange"){
        let t=br.trim().trim_matches(|c| c=='['||c==']'); if let Some((a,b))=t.split_once(':'){ let msb:a_parse(a); let _=msb; let msb_v=a.trim().parse::<u32>().unwrap_or(0); let lsb=b.trim().parse::<u32>().unwrap_or(0); off=lsb; wid=msb_v-lsb+1; }
    }
    if let Some(v)=x.child_text("lsb"){ off=v.parse().unwrap_or(off); }
    if let Some(v)=x.child_text("msb"){ let msb=v.parse::<u32>().unwrap_or(0); wid=msb-off+1; }
    // also <bit>?? not
    let mut range=None;
    if let Some(wc)=x.child("writeConstraint"){ if let Some(r)=wc.child("range"){ range=Some((r.child_text("minimum").and_then(|s|parse_int(&s).ok()).unwrap_or(0), r.child_text("maximum").and_then(|s|parse_int(&s).ok()).unwrap_or(0))); } }
    Field{ name:x.child_text("name").unwrap_or_default(), description:x.child_text("description"), bit_offset:off, bit_width:wid,
      access:x.child_text("access").and_then(|s| Access::parse(&s)), enums:parse_enums(x), derived_from:x.attr("derivedFrom"), dim:get_dim(x),
      modified_write_values:x.child_text("modifiedWriteValues").and_then(|s| Mwv::parse(&s)), read_action:x.child_text("readAction").and_then(|s| ReadAction::parse(&s)), write_constraint_range:range }
}
fn a_parse(s:&str){}
pub fn parse_register(x:&Xml)->Register{
    let fields=if let Some(f)=x.child("fields"){ f.children_named("field").map(parse_field).collect() } else { vec![] };
    Register{ name:x.child_text("name").unwrap_or_default(), display_name:x.child_text("displayName"), description:x.child_text("description"), address_offset:x.child_text("addressOffset").and_then(|s|parse_int(&s).ok()).unwrap_or(0), props:Props::parse(x), fields, derived_from:x.attr("derivedFrom"), dim:get_dim(x), alternate_group:x.child_text("alternateGroup"), alternate_register:x.child_text("alternateRegister"), modifier:x.child_text("modifier") }
}
pub fn parse_cluster(x:&Xml)->Cluster{
    let mut children=vec![];
    // cluster can contain registers and clusters directly (SVD wraps? spec: cluster contains register/cluster elements directly)
    for c in &x.children {
        if c.name=="register"{ children.push(BlockElem::Register(parse_register(c))); }
        else if c.name=="cluster"{ children.push(BlockElem::Cluster(parse_cluster(c))); }
    }
    Cluster{ name:x.child_text("name").unwrap_or_default(), description:x.child_text("description"), address_offset:x.child_text("addressOffset").and_then(|s|parse_int(&s).ok()).unwrap_or(0), props:Props::parse(x), children, derived_from:x.attr("derivedFrom"), dim:get_dim(x), alternate_cluster:x.child_text("alternateCluster"), header_struct_name:x.child_text("headerStructName") }
}
fn parse_block(parent:&Xml)->Vec<BlockElem>{
    let mut out=vec![];
    if let Some(regs)=parent.child("registers"){
        for c in &regs.children {
            if c.name=="register"{ out.push(BlockElem::Register(parse_register(c))); }
            else if c.name=="cluster"{ out.push(BlockElem::Cluster(parse_cluster(c))); }
        }
    }
    out
}
pub fn parse_peripheral(x:&Xml)->Peripheral{
    let mut interrupts=vec![];
    for i in x.children_named("interrupt"){ interrupts.push(Interrupt{name:i.child_text("name").unwrap_or_default(), description:i.child_text("description"), value:i.child_text("value").and_then(|s|parse_int(&s).ok()).unwrap_or(0)}); }
    Peripheral{ name:x.child_text("name").unwrap_or_default(), description:x.child_text("description"), group_name:x.child_text("groupName"), base_address:x.child_text("baseAddress").and_then(|s|parse_int(&s).ok()).unwrap_or(0), interrupts, registers:parse_block(x), derived_from:x.attr("derivedFrom"), dim:get_dim(x), props:Props::parse(x), header_struct_name:x.child_text("headerStructName"), alternate_peripheral:x.child_text("alternatePeripheral") }
}

#[derive(Debug)]
pub struct ParseError(pub String);
pub fn parse_device(xml:&Xml)->Result<Device,ParseError>{
    if xml.name!="device"{ return Err(ParseError("the document does not have a root node".into())); }
    let name=match xml.child_text("name"){ Some(n) if !n.is_empty()=>n, _=> return Err(ParseError(format!("0: Parsing unknown device at {}:{}\n1: Expected a `<name>` tag, found none", xml.line, xml.col))) };
    if xml.child("peripherals").is_none(){
        // position: oracle uses device tag pos
        return Err(ParseError(format!("0: Parsing device `{}` at {}:{}\n1: Expected a `<peripherals>` tag, found none", name, xml.line, xml.col)));
    }
    // validate baseAddress parsing for nicer errors? parse_int failures already defaulted; need detect invalid numbers in key spots
    // We'll do a validation pass for numeric elements
    if let Err(e)=validate_numbers(xml){ return Err(e); }
    let cpu=xml.child("cpu").map(|c| Cpu{ name:c.child_text("name").unwrap_or_default(), nvic_prio_bits:c.child_text("nvicPrioBits").and_then(|s| parse_int(&s).ok()), vendor_systick_config:c.child_text("vendorSystickConfig").map(|s| parse_bool(&s)) });
    let peripherals=xml.child("peripherals").unwrap().children_named("peripheral").map(parse_peripheral).collect::<Vec<_>>();
    if peripherals.is_empty(){
        return Err(ParseError("`Device error: Device must contain at least one peripheral".into()));
    }
    Ok(Device{ name, version:xml.child_text("version"), description:xml.child_text("description"), cpu, peripherals, props:Props::parse(xml), address_unit_bits:xml.child_text("addressUnitBits").and_then(|s|parse_int(&s).ok()), width:xml.child_text("width").and_then(|s|parse_int(&s).ok()) })
}
fn validate_numbers(xml:&Xml)->Result<(),ParseError>{
    // check baseAddress elements anywhere
    fn walk(x:&Xml, dev:&str, periph:Option<&str>)->Result<(),ParseError>{
        let mut p=periph;
        if x.name=="peripheral"{ /* name child */ }
        for c in &x.children{
            if c.name=="baseAddress"{
                let v=c.text_trim(); if parse_int(&v).is_err(){
                    // Construct context similar to oracle: In device `X` / In peripheral `P` / Parsing unknown baseAddress at line:col / Failed...
                    // Find peripheral name by searching ancestors is hard; caller handles? We'll generic here overwritten below
                }
            }
            walk(c,dev,p)?;
        }
        Ok(())
    }
    let _=walk(xml,"",None);
    // Specific check: peripherals baseAddress
    if let Some(per)=xml.child("peripherals"){
        for pxml in per.children_named("peripheral"){
            let pname=pxml.child_text("name").unwrap_or_default();
            if let Some(ba)=pxml.child("baseAddress"){
                if parse_int(&ba.text_trim()).is_err(){
                    return Err(ParseError(format!("0: In device `{}`\n1: In peripheral `{}`\n2: Parsing unknown baseAddress at {}:{}\n3: Failed to parse `invalid digit found in string`", xml.child_text("name").unwrap_or_default(), pname, ba.line, ba.col)));
                }
            }
        }
    }
    Ok(())
}

// Helper for derived and expanded lookups will be in gen.
pub type AnyMap = BTreeMap<String,String>;
RS
"}

