        if let Some((a,b))=t.split_once('-'){
            let a=a.trim(); let b=b.trim();
            if let (Ok(av),Ok(bv))=(a.parse::<i64>(), b.parse::<i64>()){ if bv>=av { return (av..=bv).map(|v|v.to_string()).collect(); } }
            let ac=a.chars().next(); let bc=b.chars().next();
