use std::sync::atomic::{AtomicU8, Ordering};
pub static LEVEL: AtomicU8 = AtomicU8::new(3);
pub fn set_level_from_str(s:&str){ LEVEL.store(match s{ "off"=>0,"error"=>1,"warn"=>2,"info"=>3,"debug"=>4,"trace"=>5,_=>3}, Ordering::Relaxed); }
pub fn level() -> u8 { LEVEL.load(Ordering::Relaxed) }
pub fn enabled(l:u8)->bool{ level()>=l }
pub fn log_msg(l:u8, target:&str, msg:&str){
    if !enabled(l){ return; }
    let name=match l{1=>"ERROR",2=>"WARN",3=>"INFO",4=>"DEBUG",5=>"TRACE",_=>"INFO"};
    let mut lines=msg.lines();
    // msg.lines drops trailing empty lines; oracle messages mostly no trailing.
    if let Some(first)=lines.next(){ eprintln!("[{:<5} {}] {}", name, target, first); } else { eprintln!("[{:<5} {}] ", name, target); }
    for line in lines { eprintln!("    {}", line); }
    // If msg ends with \n, lines ignores final, fine
}
pub fn info(target:&str,msg:&str){ log_msg(3,target,msg); }
pub fn warn(target:&str,msg:&str){ log_msg(2,target,msg); }
pub fn debug(target:&str,msg:&str){ log_msg(4,target,msg); }
pub fn error(msg:&str){ log_msg(1,"svd2rust",msg); }
pub fn err_with_context(context:&str, cause:&str){
    // cause may contain newlines; format in anyhow style as seen
    let mut m=String::new(); m.push_str(context); m.push_str("\n\nCaused by:\n");
    for (i,line) in cause.lines().enumerate(){ if i>0 { m.push('\n'); } m.push_str("    "); m.push_str(line); }
    error(&m);
}
RS
