use crate::config::{Config, Target, Edition};
use crate::model::*;
use crate::util::*;
use crate::log;
use std::collections::{BTreeMap, HashMap, HashSet};

pub struct RenderErr(pub Vec<String>);
impl RenderErr {
    pub fn single(s:String)->Self{ Self(vec![s]) }
    pub fn cause(&self)->String{
        if self.0.len()==1 { self.0[0].clone() } else { self.0.iter().enumerate().map(|(i,s)| format!("{}: {}", i, s)).collect::<Vec<_>>().join("\n") }
    }
}

#[derive(Clone)]
pub struct Eff { pub size:u32, pub access:Access, pub reset:Option<u64>, pub reset_mask:Option<u64> }
pub fn eff_register(device:&Device, periph:&Peripheral, ancestors:&[Props], reg:&Register)->Eff{
    let mut p=device.props.clone();
    p = periph.props.merge_over(&p);
    for a in ancestors { p = a.merge_over(&p); }
    p = reg.props.merge_over(&p);
    Eff{ size:p.size.unwrap_or(32), access:p.access.unwrap_or(Access::ReadWrite), reset:p.reset_value, reset_mask:p.reset_mask }
}
pub fn reg_ux(size:u32)->&'static str{ if size<=8 {"u8"} else if size<=16 {"u16"} else if size<=32 {"u32"} else {"u64"} }
pub fn field_ux(width:u32)->&'static str{ if width<=1 {"bool"} else if width<=8 {"u8"} else if width<=16 {"u16"} else if width<=32 {"u32"} else {"u64"} }
pub fn mask(width:u32)->u64{ if width>=64 { u64::MAX } else if width==0 {0} else { (1u64<<width)-1 } }

pub fn desc_or_empty(desc: &Option<String>) -> String { desc.as_ref().map(|s| sanitize_description(s)).unwrap_or_default() }
pub fn reg_desc(reg:&Register) -> String {
    match &reg.description { Some(d)=>sanitize_description(d), None=>{ log::warn("svd2rust::generate::register", &format!("Missing description for register {}", reg.name)); String::new() } }
}
pub fn sanitize_description_pub(s:&str)->String{ sanitize_description(s) }

pub struct Ctx<'a> { pub cfg:&'a Config, pub device:&'a Device }
impl<'a> Ctx<'a> {
    pub fn fmt(&self, kind:&str, name:&str, is_type:bool)->String{ apply_format(&self.cfg.ident_formats, kind, name, is_type) }
    pub fn feature_for(&self, exp_name:&str, group:Option<&String>) -> Option<String> {
        if self.cfg.feature_peripheral { Some(self.fmt("peripheral_feature", exp_name, false)) }
        else if self.cfg.feature_group { group.map(|g| self.fmt("peripheral_feature", g, false)) }
        else { None }
    }
}

pub fn render(device:&Device, cfg:&Config) -> Result<String, RenderErr> {
    let ctx=Ctx{cfg, device};
    // Debug logs used by original at info? caller does.
    log::debug("svd2rust::generate::device", match cfg.target { Target::Riscv if cfg.settings.riscv_config_present => "Rendering RISC-V specific code", Target::Riscv => "Rendering interrupts", _ => "Rendering interrupts" });
    let mut src=String::new();
    // crate attributes
    let dev_doc = format!("Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (63c65c2 2026-06-11))\n\nYou can find an overview of the generated API [here].\n\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\n\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n[repository]: https://github.com/rust-embedded/svd2rust", device.name.to_uppercase());
    let skip=cfg.skip_crate_attributes;
    let make=cfg.make_mod;
    if cfg.target==Target::Msp430 && !skip {
        // msp feature inner attribute comes before doc; if make_mod ? likely still only doc? We'll follow: if !make? oracle make+ msp unknown. Emit feature when not skip regardless then doc.
        src.push_str("#![feature(abi_msp430_interrupt)]\n");
    }
    if !skip {
        if make {
            src.push_str(&format!("#![doc = \"{}\"]\n", escape_rust_string(&dev_doc)));
        } else {
            src.push_str(&format!("#![doc = \"{}\"]\n#![allow(non_camel_case_types)]\n#![allow(non_snake_case)]\n#![no_std]\n#![cfg_attr(docsrs, feature(doc_cfg))]\n", escape_rust_string(&dev_doc)));
        }
    }
    // The generic/NVIC chunk behaviour in make_mod+skip+generic_mod case: generic decl is omitted.
    let omit_generic_decl = skip && make && cfg.generic_mod;
    // NVIC
    let mut after_top = String::new();
