// ---------- Peripheral expansion ----------
#[derive(Debug, Clone)]
pub struct PExp {
    pub name_expanded: String,
    pub orig_name: String,
    pub desc: String,
    pub group: Option<String>,
    pub base_address: u64,
    pub registers: Vec<BlockElem>,
    pub interrupts: Vec<Interrupt>,
    pub derived_from: Option<String>,
    pub base_mod: String, // module of base peripheral for RB / derived use
    pub own_mod: String,
    pub type_name: String,
    pub spec_name: String,
    pub singleton_name: String,
    pub feature: Option<String>,
    pub dim_group: Option<String>,
    pub dim_first: bool,
    pub props: Props,
}
impl PExp {
    pub fn original_name_for_debug(&self)->String{ self.orig_name.clone() }
    pub fn has_registers(&self, _device:&Device, _cfg:&Config)->bool{ !self.registers.is_empty() }
}
pub fn base_name_of(path:&str)->String{ path.split('.').last().unwrap_or(path).to_string() }
pub fn expand_peripherals(device:&Device, cfg:&Config, ctx:&Ctx)->Result<Vec<PExp>,RenderErr>{
    let mut out=vec![];
    // map by name
    let find_periph=|name:&str| -> Option<&Peripheral> {
        let b=base_name_of(name);
        device.peripherals.iter().find(|p| p.name==b || strip_dim(&p.name)==b)
    };
    for per in &device.peripherals {
        let desc_default = per.description.clone();
        if let Some(dim)=&per.dim {
            let indices=dim_indices(dim.dim, dim.index.as_deref());
            let group_key=Some(per.name.clone());
            for (pos, idx) in indices.iter().enumerate(){
                let name_exp=expand_dim_name(&per.name, idx);
                let addr=per.base_address + (dim.increment as u64)*(pos as u64) + cfg.base_address_shift;
                let mut regs=per.registers.clone();
                // interrupts name expansion
                let mut ints=per.interrupts.clone(); for i in &mut ints { i.name=expand_dim_name(&i.name, idx); }
                let pexp=make_pexp(ctx, per, name_exp, addr, regs, ints, None, desc_default.clone(), group_key.clone(), pos==0);
                out.push(pexp);
            }
        } else if let Some(derived)=&per.derived_from {
            let base=find_periph(derived).cloned();
            let (regs, ints, bdesc, bgroup) = if let Some(b)=&base {
                ( if per.registers.is_empty(){ b.registers.clone()} else {per.registers.clone()},
