fn make_pexp(ctx:&Ctx, per:&Peripheral, name_exp:String, addr:u64, regs:Vec<BlockElem>, ints:Vec<Interrupt>, derived:Option<String>, desc:Option<String>, dim_group:Option<String>, dim_first:bool)->PExp{
