        for i in &p.interrupts {
            let name=ctx.fmt("interrupt", &i.name, true);
            v.push(IntInfo{name, desc:i.description.as_ref().map(|s| sanitize_description(s)).unwrap_or_else(|| i.name.clone()), value:i.value, feature:feat.clone(), exp_name:p.name_expanded.clone()});
