fn cfg_attr_str(feat:&Option<String>)->String{ if let Some(f)=feat{ format!("#[cfg(feature = \"{}\")]\n", crate::util::escape_rust_string(f)) } else { String::new() } }
fn interrupt_enum_variants(ints:&[IntInfo], cfg:&Config, ctx:&Ctx, include_feature:bool)->String{
    let mut s=String::new(); let mut last_feat:Option<String>=None; let mut first=true;
    for i in ints {
        let mut emit_cfg=false;
        if include_feature {
            if let Some(f)=&i.feature { if first || last_feat.as_ref()!=Some(f){ emit_cfg=true; } }
        }
        if let Some(f)=&i.feature {
            if include_feature && emit_cfg { s.push_str(&cfg_attr_str(&i.feature)); }
            last_feat=Some(f.clone());
        } else { last_feat=None; }
        first=false;
        s.push_str(&format!("{} {} = {},\n", doc_attr(&format!("{} - {}", i.value, i.desc)), i.name, i.value));
    }
    s
}
fn interrupt_enum(ints:&[IntInfo], cfg:&Config, ctx:&Ctx, doc_text:&str, include_feature:bool)->String{
    let mut s=String::new();
    s.push_str(&doc_raw(doc_text)); s.push('\n');
    if cfg.impl_defmt.is_some(){ if let Some(f)=&cfg.impl_defmt{ s.push_str(&format!("#[cfg_attr(feature = \"{}\", derive(defmt::Format))]\n", escape_rust_string(f))); } }
    s.push_str("#[derive(Copy, Clone, Debug, PartialEq, Eq)]\n");
    if !ints.is_empty(){ s.push_str("#[repr(u16)]\n"); }
    s.push_str("pub enum Interrupt {\n");
