    let mut last_feat:Option<String>=None; let mut first=true;
    for i in ints {
        let mut emit=false;
        if let Some(f)=&i.feature { if first || last_feat.as_ref()!=Some(f){ emit=true; } }
        if emit { s.push_str(&cfg_attr_str(&i.feature)); }
        last_feat=i.feature.clone(); first=false;
        s.push_str(&format!("fn {}();\n", i.name));
    }
    s.push_str("}\n"); s
}
fn attr_link_section(cfg:&Config)->String{ if cfg.edition==Edition::E2024 {"#[unsafe(link_section = \".vector_table.interrupts\")]\n".into()} else {"#[link_section = \".vector_table.interrupts\"]\n".into()} }
fn attr_no_mangle(cfg:&Config)->String{ if cfg.edition==Edition::E2024 {"#[unsafe(no_mangle)]\n".into()} else {"#[no_mangle]\n".into()} }
fn try_from_impl(ints:&[IntInfo], ty:&str)->String{
    let mut arms=String::new(); for i in ints { arms.push_str(&format!("{} => Ok(Interrupt::{}),\n", i.value, i.name)); }
    format!("#[doc = r\" TryFromInterruptError\"]\n#[derive(Debug, Copy, Clone)]\npub struct TryFromInterruptError(());\nimpl Interrupt {{\n#[doc = r\" Attempt to convert a given value into an `Interrupt`\"]\n#[inline] pub fn try_from(value: {}) -> Result<Self, TryFromInterruptError> {{ match value {{ {} _ => Err(TryFromInterruptError(())), }} }}\n}}\n", ty, arms)
}
pub fn render_interrupts(device:&Device, cfg:&Config, ctx:&Ctx, ints:&[IntInfo])->Result<String,RenderErr>{
    let mut s=String::new();
    match cfg.target {
        Target::CortexM => {
            s.push_str(&extern_block(ints,cfg,"C",ctx));
            s.push_str("#[doc(hidden)]\n#[repr(C)]\npub union Vector { _handler: unsafe extern \"C\" fn(), _reserved: u32 }\n");
            let (n,entries)=vector_entries(ints,cfg,ctx);
            s.push_str("#[cfg(feature = \"rt\")]\n#[doc(hidden)]\n"); s.push_str(&attr_link_section(cfg)); s.push_str(&attr_no_mangle(cfg));
            s.push_str(&format!("pub static __INTERRUPTS: [Vector; {}] = [{}];\n", n, entries));
            s.push_str(&interrupt_enum(ints,cfg,ctx,"Enumeration of all the interrupts.", true));
            s.push_str("unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {\n");
            if ints.is_empty(){ s.push_str("#[inline(always)] fn number(self) -> u16 { match self {} }\n"); } else { s.push_str("#[inline(always)] fn number(self) -> u16 { self as u16 }\n"); }
            s.push_str("}\n");
        },
        Target::Msp430 => {
            s.push_str(&extern_block(ints,cfg,"msp430-interrupt",ctx));
            s.push_str("#[doc(hidden)]\n#[repr(C)]\npub union Vector { _handler: unsafe extern \"msp430-interrupt\" fn(), _reserved: u16 }\n");
            let (n,entries)=vector_entries(ints,cfg,ctx);
            s.push_str("#[cfg(feature = \"rt\")]\n#[doc(hidden)]\n"); s.push_str(&attr_link_section(cfg)); s.push_str(&attr_no_mangle(cfg)); s.push_str("#[used]\n");
            s.push_str(&format!("pub static __INTERRUPTS: [Vector; {}] = [{}];\n", n, entries));
            s.push_str(&interrupt_enum(ints,cfg,ctx,"Enumeration of all the interrupts. This enum is seldom used in application or library crates. It is present primarily for documenting the device's implemented interrupts.", true));
        },
        Target::XtensaLx => {
            s.push_str(&extern_block(ints,cfg,"C",ctx));
            s.push_str("#[doc(hidden)]\n#[repr(C)]\npub union Vector { pub _handler: unsafe extern \"C\" fn(), _reserved: u32 }\n");
            let (n,entries)=vector_entries(ints,cfg,ctx);
            s.push_str("#[cfg(feature = \"rt\")]\n#[doc(hidden)]\n"); s.push_str(&attr_no_mangle(cfg));
            s.push_str(&format!("pub static __INTERRUPTS: [Vector; {}] = [{}];\n", n, entries));
            s.push_str(&interrupt_enum(ints,cfg,ctx,"Enumeration of all the interrupts.", true));
            s.push_str(&try_from_impl(ints,"u16"));
        },
        Target::Riscv => {
            if cfg.settings.riscv_config_present {
                s.push_str(&crate::riscv_gen::render_riscv_new(device,cfg,ctx,ints));
            } else {
                log::warn("svd2rust::generate::device", "No settings file provided for RISC-V target. Using legacy interrupts rendering");
                log::warn("svd2rust::generate::device", "Please, consider migrating your PAC to riscv 0.12.0 or later");
                s.push_str(&extern_block(ints,cfg,"C",ctx));
                s.push_str("#[doc(hidden)]\n#[repr(C)]\npub union Vector { pub _handler: unsafe extern \"C\" fn(), pub _reserved: usize }\n");
                let (n,entries)=vector_entries(ints,cfg,ctx);
                s.push_str("#[cfg(feature = \"rt\")]\n#[doc(hidden)]\n"); s.push_str(&attr_no_mangle(cfg));
                s.push_str(&format!("pub static __EXTERNAL_INTERRUPTS: [Vector; {}] = [{}];\n", n, entries));
                s.push_str("#[doc(hidden)]\npub mod interrupt {\n");
                s.push_str(&interrupt_enum(ints,cfg,ctx,"Enumeration of all the interrupts.", true));
                s.push_str(&try_from_impl(ints,"u8"));
                s.push_str(include_str!("../assets/riscv_macro.rs"));
                s.push_str("}\npub use self::interrupt::Interrupt;\n");
            }
        },
        Target::Mips | Target::NoneT => {
            s.push_str("#[doc(hidden)]\npub mod interrupt {\n");
            s.push_str(&interrupt_enum(ints,cfg,ctx,"Enumeration of all the interrupts.", true));
            s.push_str(&try_from_impl(ints,"u8"));
            s.push_str("}\npub use self::interrupt::Interrupt;\n");
        },
    }
    Ok(s)
}
RS
