// ---------- Peripheral expansion ----------
#[derive(Debug, Clone)]
pub struct PExp {
    pub name_expanded: String,
    pub orig_name: String,
    pub desc: String,
    pub group: Option<String>,
    pub base_address: u64,
    pub registers: Vec<BlockElem>,
    pub interrupts: Vec<Interrupt>,
    pub derived_from: Option<String>,
    pub base_mod: String, // module of base peripheral for RB / derived use
    pub own_mod: String,
    pub type_name: String,
    pub spec_name: String,
    pub singleton_name: String,
    pub feature: Option<String>,
    pub dim_group: Option<String>,
    pub dim_first: bool,
    pub props: Props,
}
impl PExp {
    pub fn original_name_for_debug(&self)->String{ self.orig_name.clone() }
    pub fn has_registers(&self, _device:&Device, _cfg:&Config)->bool{ !self.registers.is_empty() }
}
pub fn base_name_of(path:&str)->String{ path.split('.').last().unwrap_or(path).to_string() }
pub fn expand_peripherals(device:&Device, cfg:&Config, ctx:&Ctx)->Result<Vec<PExp>,RenderErr>{
    let mut out=vec![];
    // map by name
    let find_periph=|name:&str| -> Option<&Peripheral> {
        let b=base_name_of(name);
        device.peripherals.iter().find(|p| p.name==b || strip_dim(&p.name)==b)
    };
    for per in &device.peripherals {
        let desc_default = per.description.clone();
        if let Some(dim)=&per.dim {
            let indices=dim_indices(dim.dim, dim.index.as_deref());
            let group_key=Some(per.name.clone());
            for (pos, idx) in indices.iter().enumerate(){
                let name_exp=expand_dim_name(&per.name, idx);
                let addr=per.base_address + (dim.increment as u64)*(pos as u64) + cfg.base_address_shift;
                let mut regs=per.registers.clone();
                // interrupts name expansion
                let mut ints=per.interrupts.clone(); for i in &mut ints { i.name=expand_dim_name(&i.name, idx); }
                let pexp=make_pexp(ctx, per, name_exp, addr, regs, ints, None, desc_default.clone(), group_key.clone(), pos==0);
                out.push(pexp);
            }
        } else if let Some(derived)=&per.derived_from {
            let base=find_periph(derived).cloned();
            let (regs, ints, bdesc, bgroup) = if let Some(b)=&base {
                ( if per.registers.is_empty(){ b.registers.clone()} else {per.registers.clone()},
                  if per.interrupts.is_empty(){ b.interrupts.clone()} else {per.interrupts.clone()},
                  if per.description.is_none(){ b.description.clone()} else {per.description.clone()},
                  if per.group_name.is_none(){ b.group_name.clone()} else {per.group_name.clone()} )
            } else { (per.registers.clone(), per.interrupts.clone(), per.description.clone(), per.group_name.clone()) };
            let mut p=per.clone(); p.description=bdesc; p.group_name=bgroup.clone();
            let pexp=make_pexp(ctx, &p, per.name.clone(), per.base_address + cfg.base_address_shift, regs, ints, Some(base_name_of(derived)), bdesc, None, true);
            out.push(pexp);
        } else {
            let pexp=make_pexp(ctx, per, per.name.clone(), per.base_address + cfg.base_address_shift, per.registers.clone(), per.interrupts.clone(), None, desc_default, None, true);
            out.push(pexp);
        }
    }
    Ok(out)
}
fn make_pexp(ctx:&Ctx, per:&Peripheral, name_exp:String, addr:u64, regs:Vec<BlockElem>, ints:Vec<Interrupt>, derived:Option<String>, desc:Option<String>, dim_group:Option<String>, dim_first:bool)->PExp{
    let own_mod_source = if let Some(d)=&derived { d.clone() } else { strip_dim(&per.name) };
    // own mod based on expanded name? For derived, own mod from name_exp; base mod from derived
    let own_mod=ctx.fmt("peripheral_mod", &strip_dim(&name_exp), false);
    let base_mod=if let Some(d)=&derived { ctx.fmt("peripheral_mod", &strip_dim(d), false) } else { ctx.fmt("peripheral_mod", &strip_dim(&per.name), false) };
    let _ = own_mod_source;
    PExp{
        type_name: ctx.fmt("peripheral", &name_exp, true),
        spec_name: ctx.fmt("peripheral_spec", &name_exp, true),
        singleton_name: ctx.fmt("peripheral_singleton", &name_exp, false),
        name_expanded:name_exp.clone(), orig_name:per.name.clone(), desc:desc_or_empty(&desc), group:per.group_name.clone(), base_address:addr, registers:regs, interrupts:ints, derived_from:derived, base_mod, own_mod, feature:None, dim_group, dim_first, props:per.props.clone(),
    }
}

// ---------- Interrupts ----------
#[derive(Debug, Clone)]
pub struct IntInfo { pub name:String, pub desc:String, pub value:u64, pub feature:Option<String>, pub exp_name:String }
pub fn collect_interrupts_from_pexps(pexps:&[PExp], ctx:&Ctx)->Vec<IntInfo>{
    let mut v=vec![];
    for p in pexps {
        let feat=ctx.feature_for(&p.name_expanded, p.group.as_ref());
        for i in &p.interrupts {
            let name=ctx.fmt("interrupt", &i.name, true);
            v.push(IntInfo{name, desc:i.description.as_ref().map(|s| sanitize_description(s)).unwrap_or_else(|| i.name.clone()), value:i.value, feature:feat.clone(), exp_name:p.name_expanded.clone()});
        }
    }
    v.sort_by_key(|i| i.value);
    // dedup by name (keep first)
    let mut seen=HashSet::new(); v.retain(|i| seen.insert(i.name.clone()));
    v
}
pub fn collect_interrupts(device:&Device, cfg:&Config)->Vec<IntInfo>{
    // placeholder replaced in render flow if needed; expand lightweight
    let ctx=Ctx{cfg, device};
    if let Ok(pexps)=expand_peripherals(device,cfg,&ctx){ collect_interrupts_from_pexps(&pexps,&ctx) } else { vec![] }
}
fn cfg_attr_str(feat:&Option<String>)->String{ if let Some(f)=feat{ format!("#[cfg(feature = \"{}\")]\n", crate::util::escape_rust_string(f)) } else { String::new() } }
fn interrupt_enum_variants(ints:&[IntInfo], cfg:&Config, ctx:&Ctx, include_feature:bool)->String{
    let mut s=String::new(); let mut last_feat:Option<String>=None; let mut first=true;
    for i in ints {
        let mut emit_cfg=false;
        if include_feature {
            if let Some(f)=&i.feature { if first || last_feat.as_ref()!=Some(f){ emit_cfg=true; } }
        }
        if let Some(f)=&i.feature {
            if include_feature && emit_cfg { s.push_str(&cfg_attr_str(&i.feature)); }
            last_feat=Some(f.clone());
        } else { last_feat=None; }
        first=false;
        s.push_str(&format!("{} {} = {},\n", doc_attr(&format!("{} - {}", i.value, i.desc)), i.name, i.value));
    }
    s
}
fn interrupt_enum(ints:&[IntInfo], cfg:&Config, ctx:&Ctx, doc_text:&str, include_feature:bool)->String{
    let mut s=String::new();
    s.push_str(&doc_raw(doc_text)); s.push('\n');
    if cfg.impl_defmt.is_some(){ if let Some(f)=&cfg.impl_defmt{ s.push_str(&format!("#[cfg_attr(feature = \"{}\", derive(defmt::Format))]\n", escape_rust_string(f))); } }
    s.push_str("#[derive(Copy, Clone, Debug, PartialEq, Eq)]\n");
    if !ints.is_empty(){ s.push_str("#[repr(u16)]\n"); }
    s.push_str("pub enum Interrupt {\n");
    s.push_str(&interrupt_enum_variants(ints,cfg,ctx,include_feature));
    s.push_str("}\n");
    s
}
fn vector_entries(ints:&[IntInfo], cfg:&Config, ctx:&Ctx)->(usize,String){
    if ints.is_empty(){ return (0,String::new()); }
    let max=ints.iter().map(|i| i.value).max().unwrap_or(0) as usize;
    let mut by_val:HashMap<u64,&IntInfo>=HashMap::new(); for i in ints{ by_val.entry(i.value).or_insert(i); }
    let mut s=String::new(); let mut last_feat:Option<String>=None; let mut first=true;
    for idx in 0..=max {
        if let Some(i)=by_val.get(&(idx as u64)){
            let mut emit=false;
            if let Some(f)=&i.feature { if first || last_feat.as_ref()!=Some(f){ emit=true; } }
            if emit { s.push_str(&cfg_attr_str(&i.feature)); }
            last_feat=i.feature.clone(); first=false;
            s.push_str(&format!("Vector {{ _handler: {} }},\n", i.name));
        } else { s.push_str("Vector { _reserved: 0 },\n"); }
    }
    (max+1,s)
}
fn extern_block(ints:&[IntInfo], cfg:&Config, abi:&str, ctx:&Ctx)->String{
    let mut s=String::new();
    s.push_str(&format!("#[cfg(feature = \"rt\")]\n{}extern \"{}\" {{\n", if cfg.edition==Edition::E2024 {"unsafe "} else {""}, abi));
    let mut last_feat:Option<String>=None; let mut first=true;
    for i in ints {
        let mut emit=false;
        if let Some(f)=&i.feature { if first || last_feat.as_ref()!=Some(f){ emit=true; } }
        if emit { s.push_str(&cfg_attr_str(&i.feature)); }
        last_feat=i.feature.clone(); first=false;
        s.push_str(&format!("fn {}();\n", i.name));
    }
    s.push_str("}\n"); s
}
fn attr_link_section(cfg:&Config)->String{ if cfg.edition==Edition::E2024 {"#[unsafe(link_section = \".vector_table.interrupts\")]\n".into()} else {"#[link_section = \".vector_table.interrupts\"]\n".into()} }
fn attr_no_mangle(cfg:&Config)->String{ if cfg.edition==Edition::E2024 {"#[unsafe(no_mangle)]\n".into()} else {"#[no_mangle]\n".into()} }
fn try_from_impl(ints:&[IntInfo], ty:&str)->String{
    let mut arms=String::new(); for i in ints { arms.push_str(&format!("{} => Ok(Interrupt::{}),\n", i.value, i.name)); }
    format!("#[doc = r\" TryFromInterruptError\"]\n#[derive(Debug, Copy, Clone)]\npub struct TryFromInterruptError(());\nimpl Interrupt {{\n#[doc = r\" Attempt to convert a given value into an `Interrupt`\"]\n#[inline] pub fn try_from(value: {}) -> Result<Self, TryFromInterruptError> {{ match value {{ {} _ => Err(TryFromInterruptError(())), }} }}\n}}\n", ty, arms)
}
pub fn render_interrupts(device:&Device, cfg:&Config, ctx:&Ctx, ints:&[IntInfo])->Result<String,RenderErr>{
    let mut s=String::new();
    match cfg.target {
        Target::CortexM => {
            s.push_str(&extern_block(ints,cfg,"C",ctx));
            s.push_str("#[doc(hidden)]\n#[repr(C)]\npub union Vector { _handler: unsafe extern \"C\" fn(), _reserved: u32 }\n");
            let (n,entries)=vector_entries(ints,cfg,ctx);
            s.push_str("#[cfg(feature = \"rt\")]\n#[doc(hidden)]\n"); s.push_str(&attr_link_section(cfg)); s.push_str(&attr_no_mangle(cfg));
            s.push_str(&format!("pub static __INTERRUPTS: [Vector; {}] = [{}];\n", n, entries));
            s.push_str(&interrupt_enum(ints,cfg,ctx,"Enumeration of all the interrupts.", true));
            s.push_str("unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt {\n");
            if ints.is_empty(){ s.push_str("#[inline(always)] fn number(self) -> u16 { match self {} }\n"); } else { s.push_str("#[inline(always)] fn number(self) -> u16 { self as u16 }\n"); }
            s.push_str("}\n");
        },
        Target::Msp430 => {
            s.push_str(&extern_block(ints,cfg,"msp430-interrupt",ctx));
            s.push_str("#[doc(hidden)]\n#[repr(C)]\npub union Vector { _handler: unsafe extern \"msp430-interrupt\" fn(), _reserved: u16 }\n");
            let (n,entries)=vector_entries(ints,cfg,ctx);
            s.push_str("#[cfg(feature = \"rt\")]\n#[doc(hidden)]\n"); s.push_str(&attr_link_section(cfg)); s.push_str(&attr_no_mangle(cfg)); s.push_str("#[used]\n");
            s.push_str(&format!("pub static __INTERRUPTS: [Vector; {}] = [{}];\n", n, entries));
            s.push_str(&interrupt_enum(ints,cfg,ctx,"Enumeration of all the interrupts. This enum is seldom used in application or library crates. It is present primarily for documenting the device's implemented interrupts.", true));
        },
        Target::XtensaLx => {
            s.push_str(&extern_block(ints,cfg,"C",ctx));
            s.push_str("#[doc(hidden)]\n#[repr(C)]\npub union Vector { pub _handler: unsafe extern \"C\" fn(), _reserved: u32 }\n");
            let (n,entries)=vector_entries(ints,cfg,ctx);
            s.push_str("#[cfg(feature = \"rt\")]\n#[doc(hidden)]\n"); s.push_str(&attr_no_mangle(cfg));
            s.push_str(&format!("pub static __INTERRUPTS: [Vector; {}] = [{}];\n", n, entries));
            s.push_str(&interrupt_enum(ints,cfg,ctx,"Enumeration of all the interrupts.", true));
            s.push_str(&try_from_impl(ints,"u16"));
        },
        Target::Riscv => {
            if cfg.settings.riscv_config_present {
                s.push_str(&crate::riscv_gen::render_riscv_new(device,cfg,ctx,ints));
            } else {
