fn doc_offset_range(ctx:&Ctx, m:&ElemInfo)->String{
    // Determine range display: if dim or internal >4? Observed cluster/register...
    let show_range = if m.dim.is_some(){ true } else { m.internal_size>4 };
    if show_range {
        let end = if let Some(d)=&m.dim { m.offset + m.internal_size*(d.dim as u64) } else { m.offset + m.internal_size };
        // keep_list expanded elements have dim None in layout info but original m here is layout: for keep_list code path, m.dim None and internal <=? For cluster ch0 internal8 >4 gives range using its offset (original offset) - oracle keep list ch0 doc 0x20..0x28 (layout offset differs but doc uses original offset field of layout info? layout info offset field is original, layout_offset separate) good.
        // For keep list, end should be offset+internal (layout member) - our m.offset is original base (0x20 for cluster) so fine.
        if ctx.cfg.keep_list && m.dim.is_none(){ format!("{}..{} - {}", hex_offset(m.offset), hex_offset(m.offset+m.internal_size), m.desc) } else { format!("{}..{} - {}", hex_offset(m.offset), hex_offset(end), m.desc) }
    } else {
        format!("{} - {}", hex_offset(m.offset), m.desc)
    }
}
pub fn render_block_accessor(ctx:&Ctx, m:&ElemInfo, overlap:bool, overlap_start:u64)->String{
    let mut s=String::new();
    let doc=doc_offset_range(ctx,m);
    if let Some(d)=&m.dim {
        if !ctx.cfg.keep_list && d.increment==m.internal_size {
            // array field accessor
            s.push_str(&doc_attr(&doc)); s.push('\n');
            s.push_str(&format!("#[inline(always)] pub const fn {}(&self, n: usize) -> &{} {{ &self.{}[n] }}\n", m.accessor, m.type_name, m.accessor));
            s.push_str(&doc_attr("Iterator for array of:")); s.push('\n');
            s.push_str(&doc_attr(&doc)); s.push('\n');
            s.push_str(&format!("#[inline(always)] pub fn {}_iter(&self) -> impl Iterator<Item = &{}> {{ self.{}.iter() }}\n", m.accessor, m.type_name, m.accessor));
            return s;
        } else if !ctx.cfg.keep_list {
            // pointer accessor
            let expr=ptr_expr(m.layout_offset, Some((d.increment, d.dim)));
            s.push_str(&doc_attr(&doc)); s.push('\n');
            s.push_str(&format!("#[inline(always)] pub const fn {}(&self, n: usize) -> &{} {{\n#[allow(clippy::no_effect)] [(); {}][n]; unsafe {{ &*{} }} }}\n", m.accessor, m.type_name, d.dim, expr));
            s.push_str(&doc_attr("Iterator for array of:")); s.push('\n');
            s.push_str(&doc_attr(&doc)); s.push('\n');
            s.push_str(&format!("#[inline(always)] pub fn {}_iter(&self) -> impl Iterator<Item = &{}> {{ (0..{}).map(move |n| unsafe {{ &*{} }}) }}\n", m.accessor, m.type_name, d.dim, expr));
            return s;
        }
    }
    if overlap {
        let expr=ptr_expr_single(overlap_start);
        s.push_str(&doc_attr(&doc)); s.push('\n');
        s.push_str(&format!("#[inline(always)] pub const fn {}(&self) -> &{} {{ unsafe {{ &*{} }} }}\n", m.accessor, m.type_name, expr));
        return s;
    }
    s.push_str(&doc_attr(&doc)); s.push('\n');
    s.push_str(&format!("#[inline(always)] pub const fn {}(&self) -> &{} {{ &self.{} }}\n", m.accessor, m.type_name, m.accessor));
    s
}
fn ptr_expr(offset:u64, dim:Option<(u64,u32)>)->String{
    let mut e="core::ptr::from_ref(self).cast::<u8>()".to_string();
    if offset!=0 { e.push_str(&format!(".add({})", offset)); }
    if let Some((inc,_))=dim { e.push_str(&format!(".add({} * n)", inc)); }
    e.push_str(".cast()");
    format!("core::ptr::from_ref(self).cast::<u8>(){}", &e[e.find(".cast::<u8>()").unwrap()+".cast::<u8>()".len()-".cast::<u8>()".len()..].replace("core::ptr::from_ref(self).cast::<u8>()","")) // placeholder unused
}
fn ptr_expr_single(offset:u64)->String{
    let mut e="core::ptr::from_ref(self).cast::<u8>()".to_string();
    if offset!=0 { e.push_str(&format!(".add({})", offset)); }
    e.push_str(".cast()"); e
}
