pub fn render_block_elem_module(e:&BlockElem, device:&Device, periph:&Peripheral, ancestors:&[Props], ctx:&Ctx, path:&[String]) -> Result<String,RenderErr> {
    match e {
        BlockElem::Register(r)=>{
            // derived register
            if let Some(derived)=&r.derived_from {
                return render_derived_register(r, derived, device, periph, ancestors, ctx, path);
            }
            let eff=eff_register(device,periph,ancestors,r);
            render_register(r, &eff, device, periph, ancestors, ctx, path)
        },
        BlockElem::Cluster(c)=>{
            if let Some(derived)=&c.derived_from {
                // Approximate derived cluster as alias to base cluster type/mod
                // Find base cluster name
                let base_name=base_name_of(derived);
                let type_name=ctx.fmt("cluster", &strip_dim(&c.name), true);
                let mod_name=ctx.fmt("cluster_mod", &strip_dim(&c.name), false);
                let base_type=ctx.fmt("cluster", &base_name, true);
                let base_mod=ctx.fmt("cluster_mod", &base_name, false);
                return Ok(format!("pub use {} as {};\npub use {} as {};\n", base_type, type_name, base_mod, mod_name));
            }
            let desc=desc_or_empty(&c.description);
            let type_name=ctx.fmt("cluster", &strip_dim(&c.name), true);
            let mod_name=ctx.fmt("cluster_mod", &strip_dim(&c.name), false);
            let mut anc=ancestors.to_vec(); anc.push(c.props.clone());
            let mut newpath=path.to_vec(); newpath.push(c.name.clone());
            let block=render_block(&c.children, device, periph, &anc, ctx, &type_name, &desc, if type_name!=strip_dim(&c.name) { Some(strip_dim(&c.name)) } else { None }, true, &newpath)?;
            let mut s=String::new();
            s.push_str(&doc_attr(&desc)); s.push('\n');
            s.push_str(&format!("pub use self::{}::{};\n", mod_name, type_name));
            s.push_str(&doc_raw("Cluster")); s.push('\n');
            s.push_str(&doc_attr(&desc)); s.push('\n');
            s.push_str(&format!("pub mod {} {{\n", mod_name));
            s.push_str(&block.struct_text);
            s.push_str(&block.modules_text);
            s.push_str("}\n");
            Ok(s)
        }
    }
}

fn find_register_by_path(device:&Device, path_str:&str) -> Option<(Peripheral, Vec<String>, Register)> {
    let parts:Vec<&str>=path_str.split('.').collect();
    if parts.len()>=2 {
        // peripheral.register or peripheral.cluster...register
        if let Some(per)=device.peripherals.iter().find(|p| p.name==parts[0] || strip_dim(&p.name)==parts[0]){
            let mut elems=&per.registers; let mut clusters=vec![];
            for i in 1..parts.len()-1 {
                // find cluster
                let mut found=None;
                for e in elems { if let BlockElem::Cluster(c)=e { if c.name==parts[i] || strip_dim(&c.name)==parts[i]{ found=Some(c.clone()); break; } } }
                if let Some(c)=found { clusters.push(c.name.clone()); // leak children by cloning into static? Instead we return cluster names and register found below via traversal cloning
                    // traverse using owned clone
                    let children=c.children.clone();
                    // We need to continue; store in a temp owned vec via Box leak is messy. Use recursive helper below instead.
                    let _=children;
                } else { return None; }
            }
            // Use recursive search
            fn search(elems:&[BlockElem], parts:&[&str], idx:usize, clusters:&mut Vec<String>) -> Option<Register>{
                if idx==parts.len()-1 { for e in elems { if let BlockElem::Register(r)=e { if r.name==parts[idx]{ return Some(r.clone()); } } } None }
                else { for e in elems { if let BlockElem::Cluster(c)=e { if c.name==parts[idx]{ clusters.push(c.name.clone()); return search(&c.children, parts, idx+1, clusters); } } } None }
            }
            let mut cl=vec![]; if let Some(r)=search(&per.registers, &parts, 1, &mut cl){ return Some((per.clone(), cl, r)); }
            return None;
        }
    }
    // single name: search all peripherals
    for per in &device.peripherals {
        fn search1(elems:&[BlockElem], name:&str, clusters:&mut Vec<String>) -> Option<Register>{
            for e in elems { match e { BlockElem::Register(r)=> if r.name==name { return Some(r.clone()); }, BlockElem::Cluster(c)=> { let mut cl2=clusters.clone(); cl2.push(c.name.clone()); if let Some(r)=search1(&c.children,name,&mut cl2.clone()){ return Some(r); } } } } None
        }
        let mut cl=vec![]; if let Some(r)=search1(&per.registers, path_str, &mut cl){ return Some((per.clone(), cl, r)); }
    }
    None
}
fn register_module_path(ctx:&Ctx, per:&Peripheral, clusters:&[String], reg:&Register) -> Vec<String> {
    let mut v=vec![ctx.fmt("peripheral_mod", &strip_dim(&per.name), false)];
    for c in clusters { v.push(ctx.fmt("cluster_mod", &strip_dim(c), false)); }
    // register eff name
    let eff=if let Some(g)=&reg.alternate_group { if ctx.cfg.ignore_groups { strip_dim(&reg.name)} else { format!("{}_{}",g,strip_dim(&reg.name)) } } else { strip_dim(&reg.name) };
    v.push(ctx.fmt("register_mod", &eff, false)); v
}
fn render_derived_register(r:&Register, derived:&str, device:&Device, periph:&Peripheral, ancestors:&[Props], ctx:&Ctx, path:&[String]) -> Result<String,RenderErr> {
    let _=ancestors;
    let found=find_register_by_path(device, derived);
    let eff_name=if let Some(g)=&r.alternate_group { if ctx.cfg.ignore_groups { strip_dim(&r.name)} else { format!("{}_{}",g,strip_dim(&r.name)) } } else { strip_dim(&r.name) };
    let type_name=ctx.fmt("register",&eff_name,true); let mod_name=ctx.fmt("register_mod",&eff_name,false);
    if let Some((bper, bclusters, breg))=found {
        let base_eff=if let Some(g)=&breg.alternate_group { if ctx.cfg.ignore_groups { strip_dim(&breg.name)} else { format!("{}_{}",g,strip_dim(&breg.name)) } } else { strip_dim(&breg.name) };
        let base_type=ctx.fmt("register",&base_eff,true); let base_mod=ctx.fmt("register_mod",&base_eff,false);
        // same block?
