    let reg_path = format!("RegisterPath {{ block: {}, name: \"{}\" }}", block_path, reg.name);
    let field_path = format!("FieldPath {{ register: {}, name: \"{}\" }}", reg_path, field.name);
    Err(RenderErr(vec![format!("can't render peripheral '{}', group '{}'", periph.name, periph.group_name.clone().unwrap_or_else(|| "No group name".into())), format!("can't render register '{}'", reg.name), format!("enumeratedValues {} not found, parent field: {}", target, field_path)]))
}

pub fn render_register(reg:&Register, eff:&Eff, device:&Device, periph:&Peripheral, ancestors:&[Props], ctx:&Ctx, path:&[String]) -> Result<String,RenderErr> {
    let desc=reg_desc(reg);
    let eff_name=if let Some(g)=&reg.alternate_group { if ctx.cfg.ignore_groups { strip_dim(&reg.name)} else { format!("{}_{}",g,strip_dim(&reg.name)) } } else { strip_dim(&reg.name) };
    let type_name=ctx.fmt("register",&eff_name,true);
    let spec_name=ctx.fmt("register_spec",&eff_name,true);
    let mod_name=ctx.fmt("register_mod",&eff_name,false);
    let can_r=eff.access.can_read(); let can_w=eff.access.can_write();
    let mut s=String::new();
    // outer accessor doc
    let outer_doc=format!("{} ({}) register accessor: {}\n\n{}\n\nFor information about available fields see [`mod@{}`] module", eff_name_original(reg, ctx), eff.access.short(), desc, you_can_text(eff,&mod_name,false), mod_name);
    // Note eff_name_original: for alternate, use ALT_CTRL; for dim, strip %s; original case as in SVD (not formatted)
    s.push_str(&doc_attr(&outer_doc)); s.push('\n');
    if type_name!=eff_name { s.push_str(&format!("#[doc(alias = \"{}\")]\n", escape_rust_string(&eff_name))); }
    s.push_str(&format!("pub type {} = crate::Reg<{}::{}>;\n", type_name, mod_name, spec_name));
    s.push_str(&doc_attr(&desc)); s.push('\n');
    s.push_str(&format!("pub mod {} {{\n", mod_name));
    if can_r { s.push_str(&format!("{} pub type R = crate::R<{}>;\n", doc_attr(&format!("Register `{}` reader", reg.name)), spec_name)); }
    if can_w { s.push_str(&format!("{} pub type W = crate::W<{}>;\n", doc_attr(&format!("Register `{}` writer", reg.name)), spec_name)); }
    // fields processing
    // First expand derived fields info map for reexport handling
    #[derive(Debug, Clone)]
    struct FProc { field:Field, eff_access:Access, read:bool, write:bool, read_enum:Option<EnumInfo>, write_enum:Option<EnumInfo>, shared_enum:bool, derived_base:Option<(Vec<String>, Register, Field)> }
    let mut fprocs:Vec<FProc>=vec![];
    for f in &reg.fields {
        let mut field=f.clone();
        let mut derived_base=None;
        if let Some(derived)=&f.derived_from {
            if let Some((bper,bclusters,breg,bf))=find_field_by_path(device, derived){
                // inherit missing properties from base (but keep own name/offset/width if present in xml? parser default width 1 if absent is ambiguous; SVD parser would know presence. Our parse default width gives 1; if derived field in file had no bitWidth, parser may have errored in oracle, so assume own width is intended)
                if field.description.is_none(){ field.description=bf.description.clone(); }
                if field.enums.is_empty(){ field.enums=bf.enums.clone(); }
                if field.access.is_none(){ field.access=bf.access.clone(); }
                if field.modified_write_values.is_none(){ field.modified_write_values=bf.modified_write_values; }
                if field.read_action.is_none(){ field.read_action=bf.read_action; }
                derived_base=Some(( {let mut v=vec![bper.name.clone()]; v.extend(bclusters.clone()); v.push(breg.name.clone()); v}, breg, bf));
            }
        }
        let facc=field.access.unwrap_or(eff.access);
        let read=can_r && facc.can_read(); let write=can_w && facc.can_write();
        if !read && !write {
            return Err(RenderErr(vec![format!("can't render peripheral '{}', group '{}'", periph.name, periph.group_name.clone().unwrap_or_else(|| "No group name".into())), format!("can't render register '{}'", reg.name), format!("Field {}.{}.{} is not writtable or readable", periph.name, reg.name, field.name)]));
        }
        // enums resolve
        let mut read_set:Option<EnumSet>=None; let mut write_set:Option<EnumSet>=None;
        for es in &field.enums {
            let resolved=resolve_enum_set(device, es, ctx, &field, periph, reg, path)?;
            if let Some(rs)=resolved {
                match rs.usage.as_str(){ "read"=> if read_set.is_none(){read_set=Some(rs)}, "write"=> if write_set.is_none(){write_set=Some(rs)}, _=>{ if read_set.is_none(){read_set=Some(rs.clone())} if write_set.is_none(){write_set=Some(rs)} } }
            }
        }
        let shared = match (&read_set,&write_set){ (Some(a),Some(b))=> a.name==b.name && a.values.len()==b.values.len() && a.values.iter().zip(b.values.iter()).all(|(x,y)| x.name==y.name && x.value==y.value && x.is_default==y.is_default), _=>false };
        let read_enum=if read { read_set.as_ref().map(|set| process_enum(ctx,&field,set, if shared {"shared"} else {"read"}, eff)) } else { None };
        let write_enum=if write { write_set.as_ref().map(|set| process_enum(ctx,&field,set, if shared {"shared"} else {"write"}, eff)) } else { None };
        fprocs.push(FProc{field, eff_access:facc, read, write, read_enum, write_enum, shared_enum:shared, derived_base});
    }
    // Generate field types
    for fp in &fprocs {
        s.push_str(&render_field_types(ctx, fp, reg, eff, device, periph, path, &fprocs)?);
    }
    // impl R
    let readable_fields:Vec<&FProc>=fprocs.iter().filter(|f| f.read).collect();
    let writable_fields:Vec<&FProc>=fprocs.iter().filter(|f| f.write).collect();
    if can_r {
        if fprocs.is_empty() {
            // special debug for empty register
            s.push_str("impl core::fmt::Debug for R { fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result { write!(f, \"{}\", self.bits()) } }\n");
        } else if !readable_fields.is_empty() || ctx.cfg.impl_debug {
            // if impl_debug, even if no readable fields? earlier R2 case would error, so readable_fields could be empty while can_r (e.g. write-only field) -> oracle omitted impl R entirely (no debug). We'll follow: only emit impl R if readable_fields not empty, unless impl_debug? Let's check impl_debug with write-only field later.
            if !readable_fields.is_empty(){
                s.push_str("impl R {\n");
                for fp in &readable_fields { s.push_str(&render_field_accessor(ctx, fp, reg, eff, true)); }
                s.push_str("}\n");
            }
            if ctx.cfg.impl_debug {
                if let Some(feat)=&ctx.cfg.impl_debug_feature { s.push_str(&format!("#[cfg(feature = \"{}\")]\n", escape_rust_string(feat))); }
                s.push_str("impl core::fmt::Debug for R { fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result { f.debug_struct(");
                s.push_str(&format!("\"{}\"", escape_rust_string(&reg.name)));
                s.push_str(")");
                for fp in &readable_fields {
                    // dim fields: accessor needs arg; original likely uses ??? skip field dim array in debug? We'll include only non-dim
                    if fp.field.dim.is_none(){
                        let acc=ctx.fmt("field_accessor", &strip_dim(&fp.field.name), false);
                        s.push_str(&format!(".field(\"{}\", &self.{}())", acc, acc));
                    } else {
                        // For dim field, debug likely ??? use base accessor with ??? We'll skip for now
                    }
                }
                s.push_str(".finish() } }\n");
            }
        } else {
            // can_r but no readable fields and not empty register: nothing (observed)
        }
    }
    if can_w {
        // write-only debug for Reg if not readable and impl_debug
        if !can_r && ctx.cfg.impl_debug {
            if let Some(feat)=&ctx.cfg.impl_debug_feature { s.push_str(&format!("#[cfg(feature = \"{}\")]\n", escape_rust_string(feat))); }
            s.push_str(&format!("impl core::fmt::Debug for crate::generic::Reg<{}> {{ fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {{ write!(f, \"(not readable)\") }} }}\n", spec_name));
        }
        if fprocs.is_empty() {
            s.push_str("impl W { }\n");
        } else if !writable_fields.is_empty() {
            s.push_str("impl W {\n");
            for fp in &writable_fields { s.push_str(&render_field_accessor(ctx, fp, reg, eff, false)); }
            s.push_str("}\n");
        }
    } else if fprocs.is_empty() && can_r {
        // empty read-only? R debug already handled; no W
    }
    // If empty register and both can_r/can_w, above produced Debug R and impl W {} in order observed: Debug was after R/W types before impl W; our code can_r branch emitted Debug, can_w emitted impl W. Good.
    // Spec
    let inner_doc=format!("{}\n\n{}", desc, you_can_text(eff,&mod_name,true));
    s.push_str(&doc_attr(&inner_doc)); s.push('\n');
    s.push_str(&format!("pub struct {};\n", spec_name));
    s.push_str(&format!("impl crate::RegisterSpec for {} {{ type Ux = {}; }}\n", spec_name, reg_ux(eff.size)));
    if can_r { s.push_str(&format!("{} impl crate::Readable for {} {{}}\n", doc_attr(&format!("`read()` method returns [`{}::R`](R) reader structure", mod_name)), spec_name)); }
    if can_w {
        // bitmaps
        let mut zero=0u64; let mut one=0u64;
        for fp in &fprocs { if fp.write { if let Some(mwv)=fp.field.modified_write_values { let m=mask(fp.field.bit_width)<<fp.field.bit_offset; match mwv { Mwv::ZeroToClear|Mwv::ZeroToSet|Mwv::ZeroToToggle=> zero|=m, Mwv::OneToSet|Mwv::OneToClear|Mwv::OneToToggle=> one|=m } } } }
        let mut inner=format!("type Safety = crate::Unsafe;");
        if zero!=0 { inner.push_str(&format!(" const ZERO_TO_MODIFY_FIELDS_BITMAP: {} = {};", reg_ux(eff.size), hex_literal(zero))); }
        if one!=0 { inner.push_str(&format!(" const ONE_TO_MODIFY_FIELDS_BITMAP: {} = {};", reg_ux(eff.size), hex_literal(one))); }
        s.push_str(&format!("{} impl crate::Writable for {} {{ {} }}\n", doc_attr(&format!("`write(|w| ..)` method takes [`{}::W`](W) writer structure", mod_name)), spec_name, inner));
    }
    if let Some(reset)=eff.reset {
        let (const_text, doc_val)=if reset==0 { (String::new(), "0".to_string()) } else { (format!(" const RESET_VALUE: {} = {};", reg_ux(eff.size), hex_literal(reset)), hex_literal(reset)) };
        s.push_str(&format!("{} impl crate::Resettable for {} {{{} }}\n", doc_attr(&format!("`reset()` method sets {} to value {}", reg.name, doc_val)), spec_name, const_text));
    }
    s.push_str("}\n");
    Ok(s)
}
fn eff_name_original(reg:&Register, ctx:&Ctx)->String{
    if let Some(g)=&reg.alternate_group { if ctx.cfg.ignore_groups { strip_dim(&reg.name)} else { format!("{}_{}",g,strip_dim(&reg.name)) } } else { strip_dim(&reg.name) }
}
RS
"}

