#[derive(Debug, Clone)]
pub struct EnumValP { pub name:String, pub variant:String, pub accessor:String, pub assigned:u64, pub desc:String, pub is_default:bool }
#[derive(Debug, Clone)]
pub struct EnumInfo { pub type_name:String, pub values:Vec<EnumValP>, pub ux:String, pub width:u32, pub safe:bool, pub direct:bool, pub has_default:bool }
pub fn process_enum(ctx:&Ctx, field:&Field, set:&EnumSet, kind:&str, eff:&Eff)->EnumInfo{
    let base = if ctx.cfg.field_names_for_enums || set.name.is_none() { strip_dim(&field.name) } else { set.name.clone().unwrap() };
    let type_name=match kind{ "read"=>ctx.fmt("enum_read_name",&base,true), "write"=>ctx.fmt("enum_write_name",&base,true), _=>ctx.fmt("enum_name",&base,true) };
    let mut vals=vec![];
    for v in &set.values {
        let assigned=if v.is_default { mask(field.bit_width) } else { v.value };
        let desc=v.description.as_ref().map(|s| sanitize_description(s)).unwrap_or_else(|| format!("`{:b}`", assigned));
        vals.push(EnumValP{ name:v.name.clone(), variant:ctx.fmt("enum_value",&v.name,true), accessor:ctx.fmt("enum_value_accessor",&v.name,false), assigned, desc, is_default:v.is_default });
    }
    let has_default=vals.iter().any(|v| v.is_default);
    let covers = {
        if field.bit_width>=64 { false } else {
            let need=1u64<<field.bit_width; let mut setv=HashSet::new(); for v in &vals { if v.assigned < need { setv.insert(v.assigned); } } (setv.len() as u64)==need
        }
    };
    EnumInfo{ type_name, values:vals, ux:field_ux(field.bit_width).to_string(), width:field.bit_width, safe:has_default||covers, direct:has_default||covers, has_default }
}
pub fn enum_def(ctx:&Ctx, field:&Field, info:&EnumInfo, eff:&Eff)->String{
    let mut s=String::new();
    let fdesc=desc_or_empty(&field.description);
    let doc = if let Some(reset)=eff.reset { let fv=(reset>>field.bit_offset)&mask(field.bit_width); format!("{}\n\nValue on reset: {}", fdesc, hex_literal(fv)) } else { fdesc.clone() };
    s.push_str(&doc_attr(&doc)); s.push('\n');
    if let Some(f)=&ctx.cfg.impl_defmt { s.push_str(&format!("#[cfg_attr(feature = \"{}\", derive(defmt::Format))]\n", escape_rust_string(f))); }
    s.push_str("#[derive(Clone, Copy, Debug, PartialEq, Eq)]\n");
    if field.bit_width!=1 { s.push_str(&format!("#[repr({})]\n", info.ux)); }
    s.push_str(&format!("pub enum {} {{\n", info.type_name));
    for v in &info.values { s.push_str(&format!("{} {} = {},\n", doc_attr(&format!("{}: {}", v.assigned, v.desc)), v.variant, v.assigned)); }
    s.push_str("}\n");
    if field.bit_width==1 {
        s.push_str(&format!("impl From<{}> for bool {{\n#[inline(always)] fn from(variant: {}) -> Self {{ variant as u8 != 0 }}\n}}\n", info.type_name, info.type_name));
    } else {
        s.push_str(&format!("impl From<{}> for {} {{\n#[inline(always)] fn from(variant: {}) -> Self {{ variant as _ }}\n}}\n", info.type_name, info.ux, info.type_name));
        s.push_str(&format!("impl crate::FieldSpec for {} {{ type Ux = {}; }}\n", info.type_name, info.ux));
        s.push_str(&format!("impl crate::IsEnum for {} {{}}\n", info.type_name));
    }
    s
}
pub fn find_field_by_path(device:&Device, path_str:&str) -> Option<(Peripheral, Vec<String>, Register, Field)> {
    let parts:Vec<&str>=path_str.split('.').collect();
    if parts.len()<2 { return None; }
    // last is field, before are peripheral/register/clusters
    if let Some((per, clusters, reg))=find_register_by_path(device, &parts[..parts.len()-1].join(".")){
        if let Some(f)=reg.fields.iter().find(|f| f.name==parts[parts.len()-1]){ return Some((per, clusters, reg, f.clone())); }
    }
    None
}
pub fn resolve_enum_set(device:&Device, set:&EnumSet, ctx:&Ctx, field:&Field, periph:&Peripheral, reg:&Register, path:&[String]) -> Result<Option<EnumSet>, RenderErr> {
    if set.derived_from.is_none(){ return Ok(Some(set.clone())); }
    let derived=set.derived_from.clone().unwrap();
    // Try path resolution: path may be to a field (periph.reg.field) whose enum set with same name? or full to enum set?
    // Search for a field by derived path and take its enum set matching name or first
    if let Some((_,_,_,bf))=find_field_by_path(device, &derived){
        // choose enum set with name == set.name or usage matching or first
        let mut chosen=None;
        for es in &bf.enums { if es.name==set.name || es.name.is_some() && set.name.is_some() && es.name==set.name { chosen=Some(es.clone()); break; } }
        if chosen.is_none(){ chosen=bf.enums.first().cloned(); }
        if let Some(mut c)=chosen { if set.name.is_some(){ c.name=set.name.clone(); } c.usage=set.usage.clone(); return Ok(Some(c)); }
    }
    // Search globally for enum set named derived last segment
    let target=base_name_of(&derived);
    for per in &device.peripherals {
        fn search_es(elems:&[BlockElem], target:&str) -> Option<EnumSet>{
            for e in elems { match e { BlockElem::Register(r)=>{ for f in &r.fields { for es in &f.enums { if es.name.as_deref()==Some(target){ return Some(es.clone()); } } } }, BlockElem::Cluster(c)=> if let Some(x)=search_es(&c.children,target){ return Some(x); } } } None
        }
        if let Some(mut c)=search_es(&per.registers,&target){ if set.name.is_some(){ /* keep set name? original enum name maybe from derived set? We'll keep found name if current set has no values */ } c.usage=set.usage.clone(); if set.name.is_some(){ c.name=set.name.clone(); } return Ok(Some(c)); }
    }
    // not found error with chain built by caller
    let block_path = format!("BlockPath {{ peripheral: \"{}\", path: [{}] }}", periph.name, path.iter().skip(1).map(|s| format!("\"{}\"", s)).collect::<Vec<_>>().join(", "));
    let reg_path = format!("RegisterPath {{ block: {}, name: \"{}\" }}", block_path, reg.name);
    let field_path = format!("FieldPath {{ register: {}, name: \"{}\" }}", reg_path, field.name);
    Err(RenderErr(vec![format!("can't render peripheral '{}', group '{}'", periph.name, periph.group_name.clone().unwrap_or_else(|| "No group name".into())), format!("can't render register '{}'", reg.name), format!("enumeratedValues {} not found, parent field: {}", target, field_path)]))
}

