        if e.safe { format!("pub type {}<'a, REG> = crate::FieldWriter<'a, REG, {}, {}, crate::Safe>;", wname, f.bit_width, e.type_name) } else { format!("pub type {}<'a, REG> = crate::FieldWriter<'a, REG, {}, {}>;", wname, f.bit_width, e.type_name) }
    } else if field_ux(f.bit_width)=="u8" { format!("pub type {}<'a, REG> = crate::FieldWriter<'a, REG, {}>;", wname, f.bit_width) } else { format!("pub type {}<'a, REG> = crate::FieldWriter<'a, REG, {}, {}>;", wname, f.bit_width, field_ux(f.bit_width)) }
}
pub fn render_reader_alias_and_impl(ctx:&Ctx, f:&Field, ei:&EnumInfo, rname:&str, display:&str)->String{
    let mut s=String::new();
    s.push_str(&doc_attr(&format!("Field `{}` reader - {}", display, field_desc_for_doc(f,true)))); s.push('\n');
    s.push_str(&reader_alias_type(ctx,f,Some(&ei.type_name),rname)); s.push('\n');
    // impl
    s.push_str(&format!("impl {} {{\n", rname));
    s.push_str(&doc_attr("Get enumerated values variant")); s.push('\n');
    let ret=if ei.direct { ei.type_name.clone() } else { format!("Option<{}>", ei.type_name) };
    let mut arms=String::new();
    for v in &ei.values {
        if f.bit_width==1 {
            let pat=if v.assigned==0 {"false"} else {"true"};
            if ei.direct { arms.push_str(&format!("{} => {}::{}, ", pat, ei.type_name, v.variant)); } else { arms.push_str(&format!("{} => Some({}::{}), ", pat, ei.type_name, v.variant)); }
        } else {
            if ei.direct { arms.push_str(&format!("{} => {}::{}, ", v.assigned, ei.type_name, v.variant)); } else { arms.push_str(&format!("{} => Some({}::{}), ", v.assigned, ei.type_name, v.variant)); }
        }
    }
    if let Some(def)=ei.values.iter().find(|v| v.is_default){ arms.push_str(&format!("_ => {}::{}, ", ei.type_name, def.variant)); }
    else if !ei.direct { arms.push_str("_ => None, "); }
    s.push_str(&format!("#[inline(always)] pub const fn variant(&self) -> {} {{ match self.bits {{ {} }} }}\n", ret, arms));
    for v in &ei.values {
        s.push_str(&doc_attr(&v.desc)); s.push('\n');
        if v.is_default { s.push_str(&format!("#[inline(always)] pub fn is_{}(&self) -> bool {{ matches!(self.variant(), {}::{}) }}\n", v.accessor, ei.type_name, v.variant)); }
        else { s.push_str(&format!("#[inline(always)] pub fn is_{}(&self) -> bool {{ *self == {}::{} }}\n", v.accessor, ei.type_name, v.variant)); }
    }
    s.push_str("}\n"); s
}
pub fn render_writer_alias_and_impl(ctx:&Ctx, f:&Field, ei:&EnumInfo, wname:&str, display:&str, reg:&Register)->String{
    let _=reg; let mut s=String::new();
    s.push_str(&doc_attr(&format!("Field `{}` writer - {}", display, field_desc_for_doc(f,false)))); s.push('\n');
    s.push_str(&writer_alias_type(ctx,f,Some(ei),wname)); s.push('\n');
    if f.bit_width==1 {
        s.push_str(&format!("impl<'a, REG> {}<'a, REG> where REG: crate::Writable + crate::RegisterSpec, {{\n", wname));
    } else {
        s.push_str(&format!("impl<'a, REG> {}<'a, REG> where REG: crate::Writable + crate::RegisterSpec, REG::Ux: From<{}> {{\n", wname, ei.ux));
    }
    for v in &ei.values {
        s.push_str(&doc_attr(&v.desc)); s.push('\n');
        s.push_str(&format!("#[inline(always)] pub fn {}(self) -> &'a mut crate::W<REG> {{ self.variant({}::{}) }}\n", v.accessor, ei.type_name, v.variant));
    }
    s.push_str("}\n"); s
}
pub fn field_expr(f:&Field, eff:&Eff, shift_expr:Option<String>)->String{
    let ux=reg_ux(eff.size); let fux=field_ux(f.bit_width);
    // shift_expr overrides offset
    if f.bit_width==eff.size && f.bit_offset==0 && shift_expr.is_none(){ return "self.bits".to_string(); }
    if f.bit_width==1 {
        if let Some(sh)=shift_expr { return format!("((self.bits >> {}) & 1) != 0", sh); }
        if f.bit_offset==0 { return "(self.bits & 1) != 0".to_string(); } else { return format!("((self.bits >> {}) & 1) != 0", f.bit_offset); }
    }
    let m=mask(f.bit_width); let mlit=hex_literal(m);
    let base=if let Some(sh)=shift_expr { format!("((self.bits >> {}) & {})", sh, mlit) } else if f.bit_offset==0 { format!("(self.bits & {})", mlit) } else { format!("((self.bits >> {}) & {})", f.bit_offset, mlit) };
    if fux!=ux { format!("{} as {}", base, fux) } else { base }
}
pub fn render_field_accessor(ctx:&Ctx, fp:&FProc, reg:&Register, eff:&Eff, is_read:bool)->String{
    let f=&fp.field; let mut s=String::new();
    let acc=field_accessor_name(ctx,f);
    let (tname, _spec) = if is_read { (reader_type_name(ctx,f), "".to_string()) } else { (writer_type_name(ctx,f), ctx.fmt("register_spec", &eff_name_original(reg,ctx), true)) };
    let spec_name=ctx.fmt("register_spec", &eff_name_original(reg,ctx), true);
    let desc=desc_or_empty(&f.description);
    if let Some(d)=&f.dim {
        let indices=dim_indices(d.dim, d.index.as_deref());
        let first_expanded=expand_dim_name(&f.name, indices.first().cloned().unwrap_or_default().as_str());
        // array accessor
        let docs:Vec<String>=vec![desc.clone(), String::new(), format!("<div class=\"warning\">`n` is number of field in register. `n == 0` corresponds to `{}` field.</div>", first_expanded)];
        for doc in &docs { s.push_str(&doc_attr(doc)); s.push('\n'); }
        let nty=if d.dim>256 {"u16"} else {"u8"};
        if is_read {
            let shift = if f.bit_offset==0 { if d.increment==1 {"n".to_string()} else { format!("n * {}", d.increment)} } else { format!("{} + n * {}", f.bit_offset, d.increment) };
            // For expression, oracle uses (n * 2) parentheses in shift; field_expr with shift string containing parentheses?
            let shift_expr=if f.bit_offset==0 { format!("(n * {})", d.increment) } else { shift.clone() };
            let expr=field_expr(f,eff,Some(shift_expr));
            s.push_str(&format!("#[inline(always)] pub fn {}(&self, n: {}) -> {} {{\n#[allow(clippy::no_effect)] [(); {}][n as usize]; {}::new({}) }}\n", acc, nty, tname, d.dim, tname, expr));
            s.push_str(&doc_attr("Iterator for array of:")); s.push('\n'); s.push_str(&doc_attr(&desc)); s.push('\n');
            s.push_str(&format!("#[inline(always)] pub fn {}_iter(&self) -> impl Iterator<Item = {}> + '_ {{ (0..{}).map(move |n| {}::new({})) }}\n", acc, tname, d.dim, tname, expr));
        } else {
            let shift = if f.bit_offset==0 { if d.increment==1 {"n".to_string()} else { format!("n * {}", d.increment)} } else { format!("{} + n * {}", f.bit_offset, d.increment) };
            s.push_str(&format!("#[inline(always)] pub fn {}(&mut self, n: {}) -> {}<'_, {}> {{\n#[allow(clippy::no_effect)] [(); {}][n as usize]; {}::new(self, {}) }}\n", acc, nty, tname, spec_name, d.dim, tname, shift));
        }
        // individual
        for (pos, idx) in indices.iter().enumerate(){
            let expanded=expand_dim_name(&strip_dim(&f.name), idx);
            let acc_exp=ctx.fmt("field_accessor", &expanded, false);
            let off=f.bit_offset + (pos as u32)*(d.increment as u32);
            let mut nf=f.clone(); nf.bit_offset=off; nf.dim=None;
            let doc_text=field_bits_doc(&nf,&desc);
            s.push_str(&doc_attr(&doc_text)); s.push('\n');
            if is_read { let expr=field_expr(&nf,eff,None); s.push_str(&format!("#[inline(always)] pub fn {}(&self) -> {} {{ {}::new({}) }}\n", acc_exp, tname, tname, expr)); }
            else { s.push_str(&format!("#[inline(always)] pub fn {}(&mut self) -> {}<'_, {}> {{ {}::new(self, {}) }}\n", acc_exp, tname, spec_name, tname, off)); }
        }
        return s;
    }
    // normal
    let doc_text=field_bits_doc(f,&desc);
    s.push_str(&doc_attr(&doc_text)); s.push('\n');
    if is_read { let expr=field_expr(f,eff,None); s.push_str(&format!("#[inline(always)] pub fn {}(&self) -> {} {{ {}::new({}) }}\n", acc, tname, tname, expr)); }
    else { s.push_str(&format!("#[inline(always)] pub fn {}(&mut self) -> {}<'_, {}> {{ {}::new(self, {}) }}\n", acc, tname, spec_name, tname, f.bit_offset)); }
    s
}
pub fn field_bits_doc(f:&Field, desc:&str)->String{
    if f.bit_width==1 { if desc.is_empty(){ format!("Bit {}", f.bit_offset)} else { format!("Bit {} - {}", f.bit_offset, desc)} }
    else { if desc.is_empty(){ format!("Bits {}:{}", f.bit_offset, f.bit_offset+f.bit_width-1)} else { format!("Bits {}:{} - {}", f.bit_offset, f.bit_offset+f.bit_width-1, desc)} }
}
RS
"}

