// ---------- Peripherals ----------
pub fn render_peripheral_spec(ctx:&Ctx, p:&PExp, alias:bool)->String{
    let mut s=String::new();
    let feat=ctx.feature_for(&p.name_expanded, p.group.as_ref());
    s.push_str(&doc_attr(&p.desc)); s.push('\n');
    if alias { s.push_str(&format!("#[doc(alias = \"{}\")]\n", escape_rust_string(&p.name_expanded))); }
    let cfgstr=cfg_attr_str(&feat);
    s.push_str(&cfgstr); s.push_str(&format!("pub type {} = crate::Periph<{}>;\n", p.type_name, p.spec_name));
    s.push_str(&cfgstr); s.push_str(&format!("pub struct {};\n", p.spec_name));
    s.push_str(&cfgstr); s.push_str(&format!("impl crate::PeripheralSpec for {} {{ type RB = {}::RegisterBlock; const ADDRESS: usize = {}; const NAME: &'static str = \"{}\"; }}\n", p.spec_name, p.base_mod, hex_literal(p.base_address), escape_rust_string(&p.type_name)));
    s
}
pub fn render_peripheral(device:&Device, cfg:&Config, ctx:&Ctx, p:&PExp, all:&[PExp]) -> Result<String,RenderErr> {
    if p.registers.is_empty(){ return Ok(String::new()); }
    let mut s=String::new();
    if let Some(group)=&p.dim_group {
        if !p.dim_first { return Ok(String::new()); }
        // specs for all in group
        for sib in all.iter().filter(|x| x.dim_group.as_ref()==Some(group) && x.orig_name==p.orig_name){
            s.push_str(&render_peripheral_spec(ctx,sib,true));
        }
        // module once
        s.push_str(&render_peripheral_module(device,cfg,ctx,p)?);
        return Ok(s);
    }
    if let Some(_derived)=&p.derived_from {
        s.push_str(&render_peripheral_spec(ctx,p,false));
        let feat=ctx.feature_for(&p.name_expanded, p.group.as_ref());
        s.push_str(&doc_attr(&p.desc)); s.push('\n');
        s.push_str(&cfg_attr_str(&feat));
        s.push_str(&format!("pub use self::{} as {};\n", p.base_mod, p.own_mod));
        return Ok(s);
    }
    s.push_str(&render_peripheral_spec(ctx,p,false));
    s.push_str(&render_peripheral_module(device,cfg,ctx,p)?);
    Ok(s)
}
pub fn render_peripheral_module(device:&Device, cfg:&Config, ctx:&Ctx, p:&PExp)->Result<String,RenderErr>{
    log::debug("svd2rust::generate::peripheral", "Checking derivation information");
    log::debug("svd2rust::generate::peripheral", "Pushing cluster & register information into output");
    log::debug("svd2rust::generate::peripheral", &format!("Pushing {} register or cluster blocks into output", p.registers.len()));
    log::debug("svd2rust::generate::peripheral", "Expanding registers or clusters into Register Block Fields");
    // find peripheral object corresponding to module: original peripheral (strip)
    let periph_obj = device.peripherals.iter().find(|per| strip_dim(&per.name)==strip_dim(&p.name_expanded) || per.name==p.orig_name).cloned().unwrap_or_else(|| device.peripherals[0].clone());
    let feat=ctx.feature_for(&p.name_expanded, p.group.as_ref());
    let mut s=String::new();
    s.push_str(&doc_attr(&p.desc)); s.push('\n');
    s.push_str(&cfg_attr_str(&feat));
    s.push_str(&format!("pub mod {} {{\n", p.own_mod));
    let path=vec![periph_obj.name.clone()];
    let block=render_block(&p.registers, device, &periph_obj, &[], ctx, "RegisterBlock", "Register block", None, false, &path)?;
    s.push_str(&block.struct_text);
    s.push_str(&block.modules_text);
    s.push_str("}\n"); Ok(s)
}
pub fn render_peripherals_struct(cfg:&Config, ctx:&Ctx, singletons:&[PExp])->String{
    let mut s=String::new();
    if cfg.edition==Edition::E2024 { s.push_str("#[unsafe(no_mangle)]\n"); } else { s.push_str("#[no_mangle]\n"); }
    s.push_str("static mut DEVICE_PERIPHERALS: bool = false;\n");
    s.push_str(&doc_raw(" All the peripherals.")); s.push('\n');
    s.push_str("#[allow(non_snake_case)]\npub struct Peripherals {\n");
    // feature group tracking
    let mut seen_groups=HashSet::new();
    for p in singletons {
        let feat_opt=ctx.feature_for(&p.name_expanded, p.group.as_ref());
        let emit_feature = if ctx.cfg.feature_group && !ctx.cfg.feature_peripheral {
            if let Some(g)=&p.group { if seen_groups.contains(g){ None } else { seen_groups.insert(g.clone()); feat_opt.clone() } } else { feat_opt.clone() }
        } else { feat_opt.clone() };
        s.push_str(&doc_attr(&p.name_expanded)); s.push('\n');
        s.push_str(&cfg_attr_str(&emit_feature));
        s.push_str(&format!("pub {}: {},\n", p.singleton_name, p.type_name));
    }
    s.push_str("}\nimpl Peripherals {\n");
    s.push_str(&doc_raw(" Returns all the peripherals *once*.")); s.push('\n');
    s.push_str("#[cfg(feature = \"critical-section\")]\n#[inline] pub fn take() -> Option<Self> { critical_section::with(|_| { if unsafe { DEVICE_PERIPHERALS } { return None } Some(unsafe { Peripherals::steal() }) }) }\n");
    // docs for steal as raw multiple
    for line in [" Unchecked version of `Peripherals::take`.", "", " # Safety", "", " Each of the returned peripherals must be used at most once."] { s.push_str(&doc_raw(line)); s.push('\n'); }
    if cfg.edition==Edition::E2024 {
        s.push_str("#[inline] pub unsafe fn steal() -> Self { unsafe { DEVICE_PERIPHERALS = true } Peripherals {");
    } else {
        s.push_str("#[inline] pub unsafe fn steal() -> Self { DEVICE_PERIPHERALS = true; Peripherals {");
    }
    let mut seen_groups2=HashSet::new();
    for p in singletons {
        let feat_opt=ctx.feature_for(&p.name_expanded, p.group.as_ref());
        let emit_feature = if ctx.cfg.feature_group && !ctx.cfg.feature_peripheral {
            if let Some(g)=&p.group { if seen_groups2.contains(g){ None } else { seen_groups2.insert(g.clone()); feat_opt.clone() } } else { feat_opt.clone() }
        } else { feat_opt.clone() };
        s.push_str(&cfg_attr_str(&emit_feature));
        if cfg.edition==Edition::E2024 { s.push_str(&format!("{}: unsafe {{ {}::steal() }},\n", p.singleton_name, p.type_name)); } else { s.push_str(&format!("{}: {}::steal(),\n", p.singleton_name, p.type_name)); }
    }
    s.push_str("} }\n"); s
}
