use crate::config::*;
use crate::util::{IdentFormats, IdentFormat, Case, default_formats, legacy_formats, apply_ident_format_str};
use std::collections::HashMap;
use std::path::PathBuf;

pub struct CliRaw {
    pub input: Option<String>,
    pub output_dir: Option<String>,
    pub config: Option<String>,
    pub settings: Option<String>,
    pub edition: Option<String>,
    pub target: Option<String>,
    pub atomics: bool,
    pub atomics_feature: Option<String>,
    pub ignore_groups: bool,
    pub keep_list: bool,
    pub generic_mod: bool,
    pub feature_group: bool,
    pub feature_peripheral: bool,
    pub ident_formats: Vec<String>,
    pub ident_formats_theme: Option<String>,
    pub field_names_for_enums: bool,
    pub max_cluster_size: bool,
    pub impl_debug: bool,
    pub impl_debug_feature: Option<String>,
    pub impl_defmt: Option<String>,
    pub make_mod: bool,
    pub skip_crate_attributes: bool,
    pub strict: bool,
    pub source_type: Option<String>,
    pub reexport_core_peripherals: bool,
    pub reexport_interrupt: bool,
    pub base_address_shift: Option<String>,
    pub log: Option<String>,
}
pub enum LoadErr { ParseToml(String), Deser(String) }

fn type_name(v:&toml::Value)->String{
    match v { toml::Value::String(s)=>format!("string \"{}\"", s), toml::Value::Integer(i)=>format!("integer `{}`", i), toml::Value::Float(f)=>format!("float `{}`", f), toml::Value::Boolean(b)=>format!("boolean `{}`", b), toml::Value::Array(_)=>"array".into(), toml::Value::Table(_)=>"map".into(), toml::Value::Datetime(d)=>format!("datetime `{}`", d) }
}
fn get<'a>(m:&'a toml::value::Map<String,toml::Value>, k:&str)->Option<&'a toml::Value>{ m.get(k) }
fn as_string(v:&toml::Value, expected:&str)->Result<String,LoadErr>{
    if let toml::Value::String(s)=v{ Ok(s.clone()) } else { Err(LoadErr::Deser(format!("invalid type: {}, expected {}", type_name(v), expected))) }
}
fn as_bool(v:&toml::Value)->Result<bool,LoadErr>{ if let toml::Value::Boolean(b)=v{ Ok(*b)} else { Err(LoadErr::Deser(format!("invalid type: {}, expected a boolean", type_name(v)))) } }
fn as_u64(v:&toml::Value)->Result<u64,LoadErr>{ if let toml::Value::Integer(i)=v{ (*i).try_into().map_err(|_| LoadErr::Deser("invalid value: integer, expected u64".into())) } else { Err(LoadErr::Deser(format!("invalid type: {}, expected u64", type_name(v)))) } }

// Merge raw: config file table is base, CLI overlays are handled in field conversion below by preferring CLI raw values.
pub fn build_config(cli:CliRaw) -> Result<Config,LoadErr> {
    let mut file_map: toml::value::Map<String,toml::Value> = Default::default();
    if let Some(cfgpath)=&cli.config {
        let path=PathBuf::from(cfgpath);
        if path.exists() {
            let text=std::fs::read_to_string(&path).map_err(|e| LoadErr::ParseToml(format!("{}", e)))?;
            let val: toml::Value = text.parse::<toml::Value>().map_err(|e| LoadErr::ParseToml(e.to_string()))?;
            if let toml::Value::Table(m)=val { file_map=m; }
        }
    }
    let mut cfg=Config::default();
    // Helper getters look in file_map
    // We'll process in struct field order.
    // edition
    if let Some(v)=cli.edition.clone() {
        cfg.edition=parse_edition_str(&v)?;
    } else if let Some(v)=get(&file_map,"edition") {
        // edition can be string or map: if map, maybe {2021?} ignore
        if v.is_str(){ cfg.edition=parse_edition_str(&as_string(v,"string or map")?)?; }
        else if v.is_table(){ /* externally tagged like E2021 = {}? try key */ if let Some(map)=v.as_table(){ if map.contains_key("2021"){cfg.edition=Edition::E2021;} else if map.contains_key("2024"){cfg.edition=Edition::E2024;} else { return Err(LoadErr::Deser(format!("invalid type: {}, expected string or map", type_name(v)))); } } }
        else { return Err(LoadErr::Deser(format!("invalid type: {}, expected string or map", type_name(v)))); }
    }
    // target
    if let Some(v)=cli.target.clone(){ cfg.target=parse_target_str(&v)?; } else if let Some(v)=get(&file_map,"target"){ cfg.target=parse_target_str(&as_string(v,"enum Target")?)?; }
    // booleans and strings in order (only type validation matters for final values; if CLI overrides, file value ignored entirely so don't validate file when CLI present for scalar fields - matches merge)
    cfg.atomics = if cli.atomics { true } else if let Some(v)=get(&file_map,"atomics"){ as_bool(v)? } else { false };
    if cli.atomics { cfg.atomics=true; }
    cfg.atomics_feature = cli.atomics_feature.clone().or_else(|| get(&file_map,"atomics_feature").and_then(|v| v.as_str().map(|s|s.to_string())));
    if cli.atomics_feature.is_none(){ if let Some(v)=get(&file_map,"atomics_feature"){ let _=as_string(v,"a string")?; } }
    cfg.generic_mod = cli.generic_mod || file_bool(&file_map,"generic_mod")?;
    cfg.make_mod = cli.make_mod || file_bool(&file_map,"make_mod")?;
    cfg.skip_crate_attributes = cli.skip_crate_attributes || file_bool(&file_map,"skip_crate_attributes")?;
    cfg.ignore_groups = cli.ignore_groups || file_bool(&file_map,"ignore_groups")?;
    cfg.keep_list = cli.keep_list || file_bool(&file_map,"keep_list")?;
    cfg.strict = cli.strict || file_bool(&file_map,"strict")?;
    cfg.feature_group = cli.feature_group || file_bool(&file_map,"feature_group")?;
    cfg.feature_peripheral = cli.feature_peripheral || file_bool(&file_map,"feature_peripheral")?;
    cfg.max_cluster_size = cli.max_cluster_size || file_bool(&file_map,"max_cluster_size")?;
    cfg.impl_debug = cli.impl_debug || file_bool(&file_map,"impl_debug")?;
    cfg.impl_debug_feature = cli.impl_debug_feature.clone().or_else(|| file_string(&file_map,"impl_debug_feature").unwrap_or(None));
    cfg.impl_defmt = cli.impl_defmt.clone().or_else(|| file_string(&file_map,"impl_defmt").unwrap_or(None));
    cfg.output_dir = cli.output_dir.clone().map(PathBuf::from).or_else(|| file_string(&file_map,"output_dir").unwrap_or(None).map(PathBuf::from));
    cfg.input = cli.input.clone().map(PathBuf::from).or_else(|| file_string(&file_map,"input").unwrap_or(None).map(PathBuf::from));
    // But if cli config path is set, input field in config file could be "input" - ok
    if let Some(v)=cli.source_type.clone(){ cfg.source_type=parse_source_str(&v)?; } else if let Some(v)=get(&file_map,"source_type"){ cfg.source_type=parse_source_str(&as_string(v,"enum SourceType")?)?; }
    cfg.log_level = cli.log.clone().or_else(|| file_string(&file_map,"log_level").unwrap_or(None));
    cfg.interrupt_link_section = file_string(&file_map,"interrupt_link_section").unwrap_or(None);
    cfg.reexport_core_peripherals = cli.reexport_core_peripherals || file_bool(&file_map,"reexport_core_peripherals")?;
    cfg.reexport_interrupt = cli.reexport_interrupt || file_bool(&file_map,"reexport_interrupt")?;
    // ident formats/theme
    let theme_raw: Option<String> = cli.ident_formats_theme.clone().or_else(|| file_string(&file_map,"ident_formats_theme").unwrap_or(None));
    // Need validate theme string: only legacy expected if present (from CLI or file). If file value was non-string, file_string errors? handle
    if let Some(v)=get(&file_map,"ident_formats_theme"){ if cli.ident_formats_theme.is_none(){ let _=as_string(v,"string")?; } }
    let is_legacy = if let Some(t)=&theme_raw { if t=="legacy"{ cfg.ident_formats_theme_present=true; true } else { return Err(LoadErr::Deser(format!("unknown variant `{}`, expected `legacy`", t))); } } else { false };
    cfg.ident_formats_theme_legacy=is_legacy;
    cfg.ident_formats = if is_legacy { legacy_formats() } else { default_formats() };
    // file ident formats
    if let Some(v)=get(&file_map,"ident_formats"){
        let map=v.as_table().ok_or_else(|| LoadErr::Deser(format!("invalid type: {}, expected map", type_name(v))))?;
        for (k, entry) in map {
            if !cfg.ident_formats.contains_key(k){ continue; }
            let tbl=entry.as_table().ok_or_else(|| LoadErr::Deser(format!("invalid type: {}, expected struct IdentFormat", type_name(entry))))?;
            let mut fmt=cfg.ident_formats.get(k).unwrap().clone();
            fmt.prefix=String::new(); fmt.suffix=String::new(); fmt.case=None;
            // Actually IdentFormat defaults in serde: if fields missing, prefix/suffix empty and case None, overriding default format for that type.
            if let Some(c)=tbl.get("case"){ let cs=as_string(c,"enum Case")?; fmt.case=Some(parse_case_config(&cs)?); }
            if let Some(p)=tbl.get("prefix"){ fmt.prefix=as_string(p,"a string")?; }
            if let Some(sfx)=tbl.get("suffix"){ fmt.suffix=as_string(sfx,"a string")?; }
            cfg.ident_formats.insert(k.clone(), fmt);
        }
    }
    for spec in &cli.ident_formats { crate::util::apply_format_to_map(&mut cfg.ident_formats, spec); }
    cfg.field_names_for_enums = cli.field_names_for_enums || file_bool(&file_map,"field_names_for_enums")?;
    // base address shift
    if let Some(v)=&cli.base_address_shift {
        // oracle bug: CLI string fails deserialize
        return Err(LoadErr::Deser(format!("invalid type: string \"{}\", expected u64", v)));
    } else if let Some(v)=get(&file_map,"base_address_shift"){ cfg.base_address_shift=as_u64(v)?; }
    cfg.settings_file = cli.settings.clone().map(PathBuf::from).or_else(|| file_string(&file_map,"settings_file").unwrap_or(None).map(PathBuf::from));
    // settings inline in config file
    if let Some(v)=get(&file_map,"settings"){
        if let Some(tbl)=v.as_table(){
            if let Some(h)=tbl.get("html_url"){ if let Some(s)=h.as_str(){ cfg.settings.html_url=Some(s.to_string()); } }
            if let Some(h)=tbl.get("crate_path"){ if let Some(s)=h.as_str(){ cfg.settings.crate_path=Some(s.to_string()); } }
            if tbl.contains_key("riscv_config"){ cfg.settings.riscv_config_present=true; }
        }
    }
    // Also config file may have output/input under different names? done
    Ok(cfg)
}
fn file_bool(m:&toml::value::Map<String,toml::Value>, k:&str)->Result<bool,LoadErr>{ if let Some(v)=m.get(k){ as_bool(v)} else { Ok(false)} }
fn file_string(m:&toml::value::Map<String,toml::Value>, k:&str)->Result<Option<String>,LoadErr>{ if let Some(v)=m.get(k){ Ok(Some(as_string(v,"a string")?))} else { Ok(None)} }
pub fn parse_edition_str(s:&str)->Result<Edition,LoadErr>{ match s{ "2021"=>Ok(Edition::E2021), "2024"=>Ok(Edition::E2024), _=>Err(LoadErr::Deser(format!("unknown variant `{}`, expected `2021` or `2024`", s))) } }
pub fn parse_target_str(s:&str)->Result<Target,LoadErr>{ match s{ "cortex-m"=>Ok(Target::CortexM), "msp430"=>Ok(Target::Msp430), "riscv"=>Ok(Target::Riscv), "xtensa-lx"=>Ok(Target::XtensaLx), "mips"=>Ok(Target::Mips), "none"=>Ok(Target::NoneT), _=>Err(LoadErr::Deser(format!("unknown variant `{}`, expected one of `cortex-m`, `msp430`, `riscv`, `xtensa-lx`, `mips`, `none`", s))) } }
pub fn parse_source_str(s:&str)->Result<SourceType,LoadErr>{ match s{ "xml"=>Ok(SourceType::Xml), "yaml"=>Ok(SourceType::Yaml), "json"=>Ok(SourceType::Json), _=>Err(LoadErr::Deser(format!("unknown variant `{}`, expected one of `xml`, `yaml`, `json`", s))) } }
pub fn parse_case_config(s:&str)->Result<Case,LoadErr>{ match s{ "constant"=>Ok(Case::Constant), "pascal"=>Ok(Case::Pascal), "snake"=>Ok(Case::Snake), _=>Err(LoadErr::Deser(format!("unknown variant `{}`, expected one of `constant`, `pascal`, `snake`", s))) } }
RS
"}

