fn ident_types_string() -> String {
    // Build from HashMap to mimic randomized order of original
    let keys:Vec<&str>=vec!["register_accessor","enum_write_name","interrupt","cluster_accessor","peripheral_spec","enum_value","peripheral_mod","cluster","register_spec","register","enum_value_accessor","field_writer","field_reader","peripheral_feature","peripheral_singleton","enum_name","register_mod","enum_read_name","field_accessor","cluster_mod","peripheral"];
