    let mut collected:Vec<&&str>=map.keys().collect();
    // HashMap iteration already randomized by SipHash keys per process; use that order
    let list=collected.drain(..).map(|k| format!("\"{}\"", k)).collect::<Vec<_>>().join(", ");
    format!("Specify `-f type:prefix:case:suffix` to change default ident formatting.\nAllowed values of `type` are [{}].\nAllowed cases are `unchanged` (''), `pascal` ('p'), `constant` ('c') and `snake` ('s').\n", list)
