pub fn apply_format_to_map(formats:&mut IdentFormats, spec:&str){
    let all:Vec<&str>=spec.split(':').collect();
    if all.is_empty(){ return; }
    let kind=all[0];
    if !formats.contains_key(kind){ return; }
    let entry=formats.get_mut(kind).unwrap();
    if all.len()>=2 { entry.prefix=all[1].to_string(); }
    if all.len()>=3 { match all[2]{ "p"=>entry.case=Some(Case::Pascal), "c"=>entry.case=Some(Case::Constant), "s"=>entry.case=Some(Case::Snake), ""=>entry.case=None, _=>{} } }
    if all.len()>=4 { entry.suffix=all[3..].join(":"); }
}
