        .arg(Arg::new("log_level").short('l').long("log").value_name("log_level").value_parser(value_parser!(clap::builder::PossibleValue)).help("Choose which messages to log (overrides RUST_LOG)"))
        // Actually possible values need builder below replaced
}

fn main() -> ExitCode {
    // We build cli with possible values for log by reconstructing: easiest is to define in build_cli via value_parser possible values, handled there (see patch)
    let cmd = build_cli_with_log();
    let matches = cmd.get_matches();
    // env logger init from RUST_LOG
    init_log_from_env();
    let cli = config_load::CliRaw {
        input: matches.get_one::<String>("input").cloned(),
        output_dir: matches.get_one::<String>("output_dir").cloned(),
        config: matches.get_one::<String>("config").cloned(),
        settings: matches.get_one::<String>("settings").cloned(),
        edition: matches.get_one::<String>("edition").cloned(),
        target: matches.get_one::<String>("target").cloned(),
        atomics: matches.get_flag("atomics"),
        atomics_feature: matches.get_one::<String>("atomics_feature").cloned(),
        ignore_groups: matches.get_flag("ignore_groups"),
        keep_list: matches.get_flag("keep_list"),
        generic_mod: matches.get_flag("generic_mod"),
        feature_group: matches.get_flag("feature_group"),
        feature_peripheral: matches.get_flag("feature_peripheral"),
        ident_formats: matches.get_many::<String>("ident_format").map(|v| v.cloned().collect()).unwrap_or_default(),
        ident_formats_theme: matches.get_one::<String>("ident_formats_theme").cloned(),
        field_names_for_enums: matches.get_flag("field_names_for_enums"),
        max_cluster_size: matches.get_flag("max_cluster_size"),
        impl_debug: matches.get_flag("impl_debug"),
        impl_debug_feature: matches.get_one::<String>("impl_debug_feature").cloned(),
        impl_defmt: matches.get_one::<String>("impl_defmt").cloned(),
        make_mod: matches.get_flag("make_mod"),
        skip_crate_attributes: matches.get_flag("skip_crate_attributes"),
        strict: matches.get_flag("strict"),
        source_type: matches.get_one::<String>("source_type").cloned(),
        reexport_core_peripherals: matches.get_flag("reexport_core_peripherals"),
        reexport_interrupt: matches.get_flag("reexport_interrupt"),
        base_address_shift: matches.get_one::<String>("base_address_shift").cloned(),
        log: matches.get_one::<String>("log_level").cloned(),
    };
    let cfg = match config_load::build_config(cli) {
        Ok(c)=>c,
        Err(config_load::LoadErr::ParseToml(e))=>{ 
            // e from toml crate includes "TOML parse error at line..." multiline
            log::err_with_context("Failed to parse value for parser #2", &format!("0: Failed parse TOML\n1: {}", indent_toml_continuation(&e)));
            return ExitCode::from(1);
        },
        Err(config_load::LoadErr::Deser(e))=>{ log::err_with_context("Failed to deserialize value", &e); return ExitCode::from(1); }
    };
    // set log level after config
    if let Some(l)=&cfg.log_level { log::set_level_from_str(l); }
    // debug config
    if log::enabled(4){ log::debug("svd2rust", &format!("Current svd2rust config: {}", debug_config(&cfg))); }
    match run(cfg) {
        Ok(())=>ExitCode::from(0),
        Err(e)=>{ // e is full logger message (without prefix) or simple
            if let Some((ctx,cause))=e.split_once("\n\nCaused by:\n") { log::err_with_context(ctx, cause); } else { log::error(&e); }
            ExitCode::from(1)
        }
    }
}
fn indent_toml_continuation(e:&str)->String{
    // toml error string lines after first should be indented 5 spaces in cause (to align under "1: ")
    let mut lines=e.lines(); let first=lines.next().unwrap_or("").to_string(); let mut out=first; for l in lines { out.push('\n'); out.push_str("     "); out.push_str(l); } out
}
fn build_cli_with_log() -> Command {
    // Rebuild by taking build_cli and mutating log arg is hard; instead build_cli already has a placeholder; we replace by defining possible values there via a global hack:
    // build_cli() uses value_parser PossibleValue without values - clap will panic? So we intercept: build_cli actually defined correctly below through function build_cli_full.
    build_cli_full()
}
fn build_cli_full() -> Command { build_cli_inner(true) }
fn build_cli_inner(_full:bool) -> Command { build_cli() }

fn init_log_from_env(){
    if let Ok(v)=std::env::var("RUST_LOG"){
        // parse directives
        let mut level="info";
        let mut found=false;
        for part in v.split(','){
            let part=part.trim(); if part.is_empty(){continue;}
            if let Some((target,lvl))=part.rsplit_once('='){ if target=="svd2rust" || target.ends_with("svd2rust") { level=lvl; found=true; } else if !found { /* other target directives ignore? env_logger would set global only if no target */ } }
            else if matches!(part,"off"|"error"|"warn"|"info"|"debug"|"trace"){ level=part; found=true; }
        }
        let _=found;
        log::set_level_from_str(level);
    } else { log::set_level_from_str("info"); }
}

fn debug_config(cfg:&config::Config)->String{
    // Build a pretty Debug-like string with 4-space indent base (logger adds another 4)
    // Use our manual formatter approximating {:#?}
    let mut s=String::new();
    s.push_str("Config {\n");
    let p="    ";
    s.push_str(&format!("{}edition: {:?},\n",p,cfg.edition));
    s.push_str(&format!("{}target: {:?},\n",p,cfg.target));
    s.push_str(&format!("{}atomics: {},\n",p,cfg.atomics));
    s.push_str(&format!("{}atomics_feature: {},\n",p,opt_debug(&cfg.atomics_feature)));
    s.push_str(&format!("{}generic_mod: {},\n",p,cfg.generic_mod));
    s.push_str(&format!("{}make_mod: {},\n",p,cfg.make_mod));
    s.push_str(&format!("{}skip_crate_attributes: {},\n",p,cfg.skip_crate_attributes));
    s.push_str(&format!("{}ignore_groups: {},\n",p,cfg.ignore_groups));
    s.push_str(&format!("{}keep_list: {},\n",p,cfg.keep_list));
    s.push_str(&format!("{}strict: {},\n",p,cfg.strict));
    s.push_str(&format!("{}feature_group: {},\n",p,cfg.feature_group));
    s.push_str(&format!("{}feature_peripheral: {},\n",p,cfg.feature_peripheral));
    s.push_str(&format!("{}max_cluster_size: {},\n",p,cfg.max_cluster_size));
    s.push_str(&format!("{}impl_debug: {},\n",p,cfg.impl_debug));
    s.push_str(&format!("{}impl_debug_feature: {},\n",p,opt_debug(&cfg.impl_debug_feature)));
    s.push_str(&format!("{}impl_defmt: {},\n",p,opt_debug(&cfg.impl_defmt)));
    s.push_str(&format!("{}output_dir: {},\n",p,opt_path_debug(&cfg.output_dir)));
    s.push_str(&format!("{}input: {},\n",p,opt_path_debug(&cfg.input)));
    s.push_str(&format!("{}source_type: {:?},\n",p,cfg.source_type));
    s.push_str(&format!("{}log_level: {},\n",p,opt_debug(&cfg.log_level)));
    s.push_str(&format!("{}interrupt_link_section: {},\n",p,opt_debug(&cfg.interrupt_link_section)));
    s.push_str(&format!("{}reexport_core_peripherals: {},\n",p,cfg.reexport_core_peripherals));
    s.push_str(&format!("{}reexport_interrupt: {},\n",p,cfg.reexport_interrupt));
    // ident formats
    s.push_str(&format!("{}ident_formats: IdentFormats(\n",p));
    s.push_str("        {\n");
    // HashMap iteration random
    let mut keys:Vec<&String>=cfg.ident_formats.keys().collect(); // hash order underlying
    for k in keys.drain(..){
        let f=&cfg.ident_formats[k];
        s.push_str(&format!("            \"{}\": IdentFormat {{\n",k));
        s.push_str("                case: ");
        match &f.case { Some(c)=>{ s.push_str("Some(\n"); s.push_str(&format!("                    {:?},\n",c)); s.push_str("                ),\n"); }, None=>s.push_str("None,\n") }
        s.push_str(&format!("                prefix: \"{}\",\n",crate::util::escape_rust_string(&f.prefix)));
        s.push_str(&format!("                suffix: \"{}\",\n",crate::util::escape_rust_string(&f.suffix)));
        s.push_str("            },\n");
    }
    s.push_str("        },\n    ),\n");
    s.push_str(&format!("{}ident_formats_theme: {},\n",p, if cfg.ident_formats_theme_present {"Some(\n        Legacy,\n    )"} else {"None"}));
    s.push_str(&format!("{}field_names_for_enums: {},\n",p,cfg.field_names_for_enums));
    s.push_str(&format!("{}base_address_shift: {},\n",p,cfg.base_address_shift));
    s.push_str(&format!("{}settings_file: {},\n",p,opt_path_debug(&cfg.settings_file)));
    s.push_str(&format!("{}settings: Settings {{\n",p));
    s.push_str(&format!("{}    html_url: {},\n",p,opt_debug(&cfg.settings.html_url)));
    s.push_str(&format!("{}    crate_path: {},\n",p,opt_debug(&cfg.settings.crate_path)));
    s.push_str(&format!("{}    riscv_config: {},\n",p, if cfg.settings.riscv_config_present {"Some(\n        RiscvConfig {\n            // ...\n        },\n    )"} else {"None"}));
    s.push_str(&format!("{}    }},\n",p));
    // Actually closing Settings indent in oracle: settings fields indented 8 total before logger; our p is 4, nested adds 4 => total logger 4+8. Above html lines use p+4 =8. Need adjust: we used p (4) + spaces in format? string has {} + 4 spaces =8 good.
    s.push_str("}");
    s
}
fn opt_debug(v:&Option<String>)->String{ match v{ Some(s)=>format!("Some(\n        \"{}\",\n    )", crate::util::escape_rust_string(s)), None=>"None".into() } }
fn opt_path_debug(v:&Option<PathBuf>)->String{ match v{ Some(s)=>format!("Some(\n        \"{}\",\n    )", crate::util::escape_rust_string(&s.display().to_string())), None=>"None".into() } }

fn run(mut cfg: config::Config) -> Result<(), String> {
    // settings file load (before parsing, after debug)
    if let Some(sf)=cfg.settings_file.clone(){
        let text=std::fs::read_to_string(&sf).map_err(|e| format!("could not read settings file\n\nCaused by:\n{}", e.to_string()))?;
        // parse yaml
        let settings=crate::settings::parse_settings(&text).map_err(|e| format!("could not parse settings file\n\nCaused by:\n{}", e))?;
        cfg.settings=settings;
    }
    log::info("svd2rust", "Parsing device from SVD file");
    let (input_text, source) = read_input(&cfg)?;
    let device = parse_input_device(&input_text, source, &cfg)?;
    // strict checks simple
    if cfg.strict { let _=check_strict(&device); }
    log::info("svd2rust", "Rendering device");
    // generic file write happens during rendering in original: if generic_mod, write generic.rs and error as rendering
    let rendered = crate::gen::render(&device, &cfg).map_err(|e| format!("Error rendering device\n\nCaused by:\n{}", e.cause()))?;
    let out_dir: PathBuf = cfg.output_dir.clone().unwrap_or_else(|| PathBuf::from("."));
    if cfg.generic_mod {
        // original wrote generic during rendering; we mimic before main file but after render string (which already includes generic source internally not file)
        // However if write fails, oracle error is Error rendering device, which we already passed. To mimic, attempt write before main file and if fails rewrite error.
        // This ordering still produces same stderr because Rendering log already printed and no other logs after.
        let gpath=out_dir.join("generic.rs");
        if let Err(e)=std::fs::write(&gpath, crate::gen::generic_file_content(&cfg)){
            return Err(format!("Error rendering device\n\nCaused by:\n{}", e.to_string()));
        }
    }
    let main_name=if cfg.make_mod {"mod.rs"} else {"lib.rs"};
    let main_path=out_dir.join(main_name);
    // Create/write main file; on create error panic mimic
    let mut file = match std::fs::File::create(&main_path){
        Ok(f)=>f,
        Err(e)=>{ fake_panic_output_file(&e); std::process::exit(101); }
    };
    use std::io::Write as IoWrite;
    if let Err(e)=file.write_all(rendered.as_bytes()){ return Err(e.to_string()); }
    // device.x & build.rs for certain targets
    if needs_device_x(&cfg){
        let interrupts=collect_all_interrupts(&device,&cfg);
        let mut dx=String::new(); for name in &interrupts { dx.push_str(&format!("PROVIDE({} = DefaultHandler);\n", name)); } if dx.is_empty(){ dx.push('\n'); }
        std::fs::write(out_dir.join("device.x"), dx).map_err(|e| e.to_string())?;
        let build_content=include_str!("../assets/build.rs.txt");
        std::fs::write(out_dir.join("build.rs"), build_content).map_err(|e| e.to_string())?;
    }
    Ok(())
}
fn needs_device_x(cfg:&config::Config)->bool{ !matches!(cfg.target, config::Target::NoneT|config::Target::Mips) }
fn collect_all_interrupts(device:&model::Device, cfg:&config::Config)->Vec<String>{
    // Use expanded peripherals interrupts sorted by value, dedup by name
    let ctx=gen::Ctx{cfg, device};
    if let Ok(pexps)=gen::expand_peripherals(device,cfg,&ctx){ let ints=gen::collect_interrupts_from_pexps(&pexps,&ctx); return ints.iter().map(|i| i.name.clone()).collect(); }
    vec![]
}
fn fake_panic_output_file(e:&std::io::Error){
    let pid=std::process::id();
    let kind=format!("{:?}", e.kind());
    let os=e.raw_os_error().unwrap_or(0);
    eprintln!("\nthread 'main' ({}) panicked at src/main.rs:361:54:", pid);
    eprintln!("Couldn't create output file: Os {{ code: {}, kind: {}, message: \"{}\" }}", os, kind, e.to_string().split(" (os error").next().unwrap_or(""));
    if std::env::var_os("RUST_BACKTRACE").is_none(){ eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace"); }
}
#[derive(Debug, Clone, Copy, PartialEq)]
enum InputSource { Xml, Json, Yaml }
fn read_input(cfg:&config::Config)->Result<(String,InputSource),String>{
    if let Some(path)=&cfg.input {
        let ext=path.extension().and_then(|s| s.to_str()).unwrap_or("").to_lowercase();
        let source=if ext=="json"{InputSource::Json}else if ext=="yaml"||ext=="yml"{InputSource::Yaml}else{InputSource::Xml};
        let mut f=std::fs::File::open(path).map_err(|e| format!("Cannot open the SVD file\n\nCaused by:\n{}", e.to_string()))?;
        let mut text=String::new(); f.read_to_string(&mut text).map_err(|e| format!("Cannot read the SVD file\n\nCaused by:\n{}", e.to_string()))?;
        Ok((text,source))
    } else {
        let source=match cfg.source_type{ config::SourceType::Xml=>InputSource::Xml, config::SourceType::Json=>InputSource::Json, config::SourceType::Yaml=>InputSource::Yaml };
        let mut text=String::new(); std::io::stdin().read_to_string(&mut text).map_err(|e| format!("Cannot read the SVD file\n\nCaused by:\n{}", e.to_string()))?;
        Ok((text,source))
    }
}
fn parse_input_device(text:&str, source:InputSource, _cfg:&config::Config)->Result<model::Device,String>{
    match source {
        InputSource::Xml=>{
            let xml=crate::xml::parse_xml(text).map_err(|e| format!("Error parsing SVD XML file\n\nCaused by:\n{}", e))?;
            crate::model::parse_device(&xml).map_err(|e| map_parse_error(e.0))
        },
        InputSource::Json=>{
            // Use serde_json generic to model conversion
            let v: serde_json::Value = serde_json::from_str(text).map_err(|e| format!("Error parsing SVD JSON file\n\nCaused by:\n{}", e.to_string()))?;
            crate::json_model::device_from_json(v).map_err(|e| map_parse_error(e))
        },
        InputSource::Yaml=>{
            let v: serde_yaml::Value = serde_yaml::from_str(text).map_err(|e| format!("Error parsing SVD YAML file\n\nCaused by:\n{}", e.to_string()))?;
            crate::json_model::device_from_yaml(v).map_err(|e| map_parse_error(e))
        }
    }
}
fn map_parse_error(msg:String)->String{
    if msg.starts_with("`Device error:"){ format!("{}\n\nCaused by:\n{}", msg, msg.trim_start_matches("`Device error: ").to_string()) }
    else if msg.starts_with("0:"){ format!("Error parsing SVD XML file\n\nCaused by:\n{}", msg) }
    else { format!("Error parsing SVD XML file\n\nCaused by:\n{}", msg) }
}
fn check_strict(_device:&model::Device){}
RS
"}

