import subprocess, os, shutil, difflib, sys
ORIG="/workspace/executable"; NEW="/tmp/newbin/executable"
def run(exe,args,name,inp=None):
    d=f"/tmp/dc/{name}/{'o' if exe==ORIG else 'n'}"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d+"/out")
    r=subprocess.run([exe]+args,cwd=d,capture_output=True,text=True,input=inp)
    files={}
    for root,_,fs in os.walk(d):
        for f in fs: files[os.path.relpath(os.path.join(root,f),d)]=open(os.path.join(root,f),'rb').read()
    return r,files
def show(name,args,inp=None):
    r1,f1=run(ORIG,args,name,inp); r2,f2=run(NEW,args,name,inp)
    print(name, r1.returncode, r2.returncode)
    if r1.stdout!=r2.stdout:
        print("stdout diff")
        for l in difflib.unified_diff(r1.stdout.splitlines(),r2.stdout.splitlines(),lineterm=''):
            print(l[:1500])
    if r1.stderr!=r2.stderr:
        print("stderr diff")
        for l in difflib.unified_diff(r1.stderr.splitlines(),r2.stderr.splitlines(),lineterm=''):
            print(l[:1500])
    for k in sorted(set(f1)|set(f2)):
        if f1.get(k)!=f2.get(k):
            print("file",k,len(f1.get(k,b'')),len(f2.get(k,b'')))
            a=f1.get(k,b'').decode(errors='replace').splitlines(); b=f2.get(k,b'').decode(errors='replace').splitlines()
            for l in difflib.unified_diff(a,b,lineterm='',n=1):
                print(l[:1800])
if __name__=='__main__':
    pass
