start=s.find('fn interrupt_enum_variants')
end=s.find('fn attr_link_section')
new=r'''fn interrupt_enum_variants(ints:&[IntInfo], cfg:&Config, ctx:&Ctx, include_feature:bool)->String{
    let _=(cfg,ctx); let mut s=String::new(); let mut prev:Option<&IntInfo>=None;
    for i in ints {
        s.push_str(&doc_attr(&format!("{} - {}", i.value, i.desc))); s.push('\n');
        if include_feature {
            for f in &i.feature {
                let cont=if let Some(p)=prev { p.value+1==i.value && p.feature.contains(f) } else { false };
                if !cont { s.push_str(&cfg_attr_one(f)); }
            }
        }
        s.push_str(&format!("{} = {},\n", i.name, i.value));
        prev=Some(i);
    }
    s
}
fn emitted_features(i:&IntInfo, prev:Option<&IntInfo>)->Vec<String>{
    let mut v=vec![]; for f in &i.feature { let cont=if let Some(p)=prev { p.value+1==i.value && p.feature.contains(f) } else { false }; if !cont { v.push(f.clone()); } } v
}
'''
s=s[:start]+new+s[end:]
# vector_entries rewrite
start=s.find('fn vector_entries')
end=s.find('fn extern_block')
new2=r'''fn vector_entries(ints:&[IntInfo], cfg:&Config, ctx:&Ctx)->(usize,String){
    let _=(cfg,ctx);
    if ints.is_empty(){ return (0,String::new()); }
    let max=ints.iter().map(|i| i.value).max().unwrap_or(0) as usize;
    let mut by_val:HashMap<u64,&IntInfo>=HashMap::new(); for i in ints{ by_val.entry(i.value).or_insert(i); }
    let mut s=String::new(); let mut prev:Option<&IntInfo>=None;
    for idx in 0..=max {
        if let Some(i)=by_val.get(&(idx as u64)){
            let emitted=emitted_features(i, prev);
            if !emitted.is_empty(){
                let feats=emitted.iter().map(|f| format!("feature = \"{}\"", crate::util::escape_rust_string(f))).collect::<Vec<_>>().join(", ");
                s.push_str(&format!("#[cfg(not(all({},)))]\n", feats));
                s.push_str("Vector { _reserved: 0 },\n");
                for f in &emitted { s.push_str(&cfg_attr_one(f)); }
            }
            s.push_str(&format!("Vector {{ _handler: {} }},\n", i.name));
            prev=Some(i);
        } else { s.push_str("Vector { _reserved: 0 },\n"); }
    }
    (max+1,s)
}
'''
s=s[:start]+new2+s[end:]
# extern block rewrite
start=s.find('fn extern_block')
end=s.find('fn attr_link_section')
new3=r'''fn extern_block(ints:&[IntInfo], cfg:&Config, abi:&str, ctx:&Ctx)->String{
    let _=ctx; let mut s=String::new();
    s.push_str(&format!("#[cfg(feature = \"rt\")]\n{}extern \"{}\" {{\n", if cfg.edition==Edition::E2024 {"unsafe "} else {""}, abi));
    let mut prev:Option<&IntInfo>=None;
    for i in ints {
        if !i.feature.is_empty(){ for f in &emitted_features(i,prev){ s.push_str(&cfg_attr_one(&f)); } }
        s.push_str(&format!("fn {}();\n", i.name));
        prev=Some(i);
    }
    s.push_str("}\n"); s
}
'''
s=s[:start]+new3+s[end:]
open(p,'w').write(s)
PY
"}

