{"command":"python3 << 'PY'
p='src/util.rs'; s=open(p).read(); start=s.find('pub fn convert_case'); end=s.find('const KEYWORDS',start)
new=r'''pub fn convert_case(s:&str, case:Case)->String{
    match case{
        Case::Unchanged=> return s.to_string(),
        Case::Snake=>{
            let mut out=String::new(); let mut prev:Option<char>=None;
            for c in s.chars(){
                if c.is_uppercase(){
                    if prev.map(|p| p.is_lowercase()).unwrap_or(false){ out.push('_'); }
                    out.extend(c.to_lowercase());
                } else if !c.is_alphanumeric() && c!='_' {
                    out.push('_');
                } else { out.extend(c.to_lowercase()); }
                prev=Some(c);
            }
            return out;
        },
        Case::Constant=>{
            let mut out=String::new(); let mut prev:Option<char>=None;
            for c in s.chars(){
                if c.is_uppercase(){
                    if prev.map(|p| p.is_lowercase()).unwrap_or(false){ out.push('_'); }
                    out.extend(c.to_uppercase());
                } else if !c.is_alphanumeric() && c!='_' {
                    out.push('_');
                } else { out.extend(c.to_uppercase()); }
                prev=Some(c);
            }
            return out;
        },
        Case::Pascal=>{
            // words are alphanumeric runs; separator runs with >=2 underscores keep one underscore
            let mut words:Vec<String>=vec![]; let mut seps:Vec<usize>=vec![]; // underscore counts between words
            let mut cur=String::new(); let mut pending_us=0usize; let mut pending_sep=false;
            for c in s.chars(){
                if c.is_alphanumeric(){
                    if pending_sep && !cur.is_empty(){ words.push(cur.clone()); cur.clear(); seps.push(pending_us); }
                    pending_sep=false; pending_us=0; cur.push(c);
                } else {
                    pending_sep=true; if c=='_'{ pending_us+=1; }
                }
            }
            if !cur.is_empty(){ words.push(cur); }
            if words.is_empty(){ return if s.contains('_') { "_".to_string() } else { String::new() }; }
            let mut out=String::new();
            if s.starts_with('_'){ out.push('_'); }
            for (i,w) in words.iter().enumerate(){
                if i>0 && seps.get(i-1).map(|n| *n>=2).unwrap_or(false){ out.push('_'); }
                let mut cs=w.chars(); if let Some(f)=cs.next(){ out.extend(f.to_uppercase()); out.push_str(&cs.as_str().to_lowercase()); }
            }
            if s.ends_with('_') && !out.ends_with('_'){ out.push('_'); }
            return out;
        }
    }
}
