use crate::config::Config;
use crate::model::*;
use crate::gen::{Ctx, IntInfo};
use crate::util::*;
use crate::log;

fn enum_section(title_doc:&str, pac_attr:&str, type_name:&str, items:&[(String,u64,String)]) -> String {
    let mut s=String::new();
    s.push_str(&doc_raw(title_doc)); s.push('\n');
    s.push_str(&format!("#[riscv::pac_enum(unsafe {})]\n", pac_attr));
    s.push_str("#[derive(Debug, Clone, Copy, PartialEq, Eq)]\n");
    s.push_str(&format!("pub enum {} {{\n", type_name));
    for (name,val,desc) in items { s.push_str(&format!("{} {} = {},\n", doc_attr(&format!("{} - {}", val, desc)), name, val)); }
    s.push_str("}\n"); s
}
pub fn render_riscv_new(_device:&Device, cfg:&Config, _ctx:&Ctx, ints:&[IntInfo])->String{
    let rc = cfg.settings.riscv.as_ref();
    if let Some(rc)=rc { if rc.base_isa.is_none(){ log::warn("svd2rust::config::riscv", "No base RISC-V ISA specified in settings file."); log::warn("svd2rust::config::riscv", "If your target supports vectored mode, you must specify the base ISA."); log::warn("svd2rust::config::riscv", "Otherwise, `riscv-rt` macros will not provide start trap routines to core interrupt handlers"); } }
    let mut s=String::new();
    s.push_str(&doc_raw(" Interrupt numbers, priority levels, and HART IDs.")); s.push('\n');
    s.push_str("pub mod interrupt {\n");
    let core_items:Vec<(String,u64,String)> = rc.map(|r| r.core_interrupts.iter().map(|i| (i.name.clone(), i.value, i.description.clone().unwrap_or_else(|| i.name.clone()))).collect()).unwrap_or_default();
    let exc_items:Vec<(String,u64,String)> = rc.map(|r| r.exceptions.iter().map(|i| (i.name.clone(), i.value, i.description.clone().unwrap_or_else(|| i.name.clone()))).collect()).unwrap_or_default();
    let pri_items:Vec<(String,u64,String)> = rc.map(|r| r.priorities.iter().map(|i| (i.name.clone(), i.value, i.description.clone().unwrap_or_else(|| i.name.clone()))).collect()).unwrap_or_default();
    let hart_items:Vec<(String,u64,String)> = rc.map(|r| r.harts.iter().map(|i| (i.name.clone(), i.value, i.description.clone().unwrap_or_else(|| i.name.clone()))).collect()).unwrap_or_default();
    if !core_items.is_empty(){ s.push_str(&enum_section(" Core interrupts. These interrupts are handled by the core itself.", "CoreInterruptNumber", "CoreInterrupt", &core_items)); } else { s.push_str("pub use riscv::interrupt::Interrupt as CoreInterrupt;\n"); }
    if !exc_items.is_empty(){ s.push_str(&enum_section(" Exception sources in the device.", "ExceptionNumber", "Exception", &exc_items)); } else { s.push_str("pub use riscv::interrupt::Exception;\n"); }
    if !pri_items.is_empty(){ s.push_str(&enum_section(" Priority levels in the device", "PriorityNumber", "Priority", &pri_items)); }
    if !hart_items.is_empty(){ s.push_str(&enum_section(" HARTs in the device", "HartIdNumber", "Hart", &hart_items)); }
    s.push_str("pub use riscv::{InterruptNumber, ExceptionNumber, PriorityNumber, HartIdNumber, interrupt::{enable, disable, free, nested}};\n");
    s.push_str("pub type Trap = riscv::interrupt::Trap<CoreInterrupt, Exception>;\n");
    s.push_str(&doc_raw(" Retrieves the cause of a trap in the current hart.")); s.push('\n');
    s.push_str(&doc_raw("")); s.push('\n');
    s.push_str(&doc_raw(" If the raw cause is not a valid interrupt or exception for the target, it returns an error.")); s.push('\n');
    s.push_str("#[inline] pub fn try_cause() -> riscv::result::Result<Trap> { riscv::interrupt::try_cause() }\n");
    s.push_str(&doc_raw(" Retrieves the cause of a trap in the current hart (machine mode).")); s.push('\n');
    s.push_str(&doc_raw("")); s.push('\n');
    s.push_str(&doc_raw(" If the raw cause is not a valid interrupt or exception for the target, it panics.")); s.push('\n');
    s.push_str("#[inline] pub fn cause() -> Trap { try_cause().unwrap() }\n");
    // external
    s.push_str(&doc_raw(" External interrupts. These interrupts are handled by the external peripherals.")); s.push('\n');
    s.push_str("#[riscv::pac_enum(unsafe ExternalInterruptNumber)]\n");
    s.push_str("#[derive(Debug, Clone, Copy, PartialEq, Eq)]\n");
    s.push_str("pub enum ExternalInterrupt {\n");
    for i in ints { s.push_str(&format!("{} {} = {},\n", doc_attr(&format!("{} - {}", i.value, i.desc)), i.name, i.value)); }
    s.push_str("}\n");
    s.push_str("}\n");
    s
}
