}
fn conv(items: Vec<crate::riscv::RiscvEnumItemYaml>) -> Vec<crate::riscv::RiscvEnumItem> { items.into_iter().map(|i| crate::riscv::RiscvEnumItem{name:i.name,value:i.value,description:i.description}).collect() }
pub fn parse_settings(text:&str)->Result<Settings,String>{
    let y: SettingsYaml = serde_yaml::from_str(text).map_err(|e| e.to_string())?;
