fn ctx_err(chain:&[String], last:String)->ParseError{ let mut v=chain.to_vec(); v.push(last); ParseError(v.join("\n")) }
fn numbered_chain(chain:&[String])->String{ chain.join("\n") }
fn validate_dim(x:&Xml, kind:&str, name:&str, ctx:&[String])->Result<(),ParseError>{
    if let Some(dim_el)=x.child("dim"){
        let name_ok=name.contains("%s");
        if !name_ok {
            let mut c=ctx.to_vec(); c.push(format!("Parsing {} `{}` at {}:{}", kind, name, x.line, x.col)); c.push(format!("Name `{}` in tag `{}` is missing a %s placeholder", name, kind));
            return Err(ParseError(c.join("\n")));
        }
        if let Some(di)=x.child("dimIndex"){
            let t=di.text_trim();
            let valid={
                if let Some((a,b))=t.split_once('-'){
                    let a=a.trim(); let b=b.trim();
                    if let (Ok(av),Ok(bv))=(a.parse::<i64>(),b.parse::<i64>()){ bv>=av } else if a.len()==1 && b.len()==1 && a.chars().next().unwrap().is_ascii_alphabetic(){ b>=a } else { false }
                } else if t.contains(','){ t.split(',').all(|p| !p.trim().is_empty()) } else { !t.is_empty() }
            };
            if !valid {
                let mut c=ctx.to_vec(); c.push(format!("In {} `{}`", kind, name)); c.push(format!("Parsing unknown dimIndex at {}:{}", di.line, di.col)); c.push("Failed to parse dimIndex".into());
                // ctx for this case in oracle does not include device? It includes In device, In peripheral, then above. Our ctx currently includes 0/1 but without numbering; caller formats numbering later from \n lines? ParseError string is used as cause directly, oracle numbering is added by main cause formatting if lines start without numbers? Our parse errors currently embed "0:" etc manually for some. We'll generate numbered strings in validate and let map_parse_error pass through if starts with 0:
                return Err(ParseError(numbered_from(&c)));
            }
        }
    }
    Ok(())
}
fn numbered_from(lines:&[String])->String{ lines.iter().enumerate().map(|(i,l)| format!("{}: {}", i,l)).collect::<Vec<_>>().join("\n") }
fn validate_field(x:&Xml, ctx:&[String])->Result<(),ParseError>{
    let name=x.child_text("name");
    let fname=name.clone().unwrap_or_default();
    if name.is_none(){
        let mut c=ctx.to_vec(); c.push(format!("Parsing unknown field at {}:{}", x.line, x.col)); c.push("Expected a `<name>` tag, found none".into()); return Err(ParseError(numbered_from(&c)));
    }
    validate_dim(x,"field",&fname,ctx)?;
    let has_bitrange=x.child("bitRange").is_some(); let has_lsb_msb=x.child("lsb").is_some() && x.child("msb").is_some(); let has_off_width=x.child("bitOffset").is_some() && x.child("bitWidth").is_some();
    if !has_bitrange && !has_lsb_msb && !has_off_width {
        let mut c=ctx.to_vec(); c.push(format!("Parsing field `{}` at {}:{}", fname, x.line, x.col)); c.push("Bit range invalid, Syntax".into()); return Err(ParseError(numbered_from(&c)));
    }
    if let Some(a)=x.child("access"){
        let v=a.text_trim(); if Access::parse(&v).is_none(){
            let mut c=ctx.to_vec(); c.push(format!("In field `{}`", fname)); c.push(format!("Parsing unknown access at {}:{}", a.line, a.col)); c.push(format!("unknown access variant '{}' found", v)); return Err(ParseError(numbered_from(&c)));
        }
    }
    // bit width for enum range
    let width:u32 = if let Some(w)=x.child_text("bitWidth"){ w.parse().unwrap_or(1)} else if let Some(br)=x.child_text("bitRange"){ let t=br.trim().trim_matches(|c| c=='['||c==']'); if let Some((aa,bb))=t.split_once(':'){ aa.trim().parse::<u32>().unwrap_or(0).saturating_sub(bb.trim().parse::<u32>().unwrap_or(0))+1 } else {1}} else if x.child("msb").is_some(){ let msb=x.child_text("msb").unwrap_or_default().parse::<u32>().unwrap_or(0); let lsb=x.child_text("lsb").unwrap_or_default().parse::<u32>().unwrap_or(0); msb-lsb+1 } else {1};
    for ev in x.children_named("enumeratedValues"){
        for val in ev.children_named("enumeratedValue"){
            if let Some(vs)=val.child_text("value"){ if let Ok(v)=parse_int(&vs){ let max=if width>=64{u64::MAX}else{(1u64<<width)-1}; if v>max { let mut c=ctx.to_vec(); c.push(format!("Parsing field `{}` at {}:{}", fname, x.line, x.col)); c.push(format!("`EnumeratedValue error: Value {} out of range [0 - {}]", v, max)); return Err(ParseError(numbered_from(&c))); } } }
        }
    }
    Ok(())
}
fn validate_block(elems:&Xml, ctx:&[String])->Result<(),ParseError>{
    for c in &elems.children {
        if c.name=="register"{
            let name=c.child_text("name");
            if name.is_none(){ let mut cc=ctx.to_vec(); cc.push(format!("Parsing unknown register at {}:{}", c.line,c.col)); cc.push("Expected a `<name>` tag, found none".into()); return Err(ParseError(numbered_from(&cc))); }
            let rname=name.unwrap();
            validate_dim(c,"register",&rname,ctx)?;
            if c.child("addressOffset").is_none(){ let mut cc=ctx.to_vec(); cc.push(format!("Parsing register `{}` at {}:{}", rname,c.line,c.col)); cc.push("Expected a `<addressOffset>` tag, found none".into()); return Err(ParseError(numbered_from(&cc))); }
            let mut rctx=ctx.to_vec(); rctx.push(format!("In register `{}`", rname));
            if let Some(a)=c.child("access"){ let v=a.text_trim(); if Access::parse(&v).is_none(){ let mut cc=rctx.clone(); cc.push(format!("Parsing unknown access at {}:{}",a.line,a.col)); cc.push(format!("unknown access variant '{}' found",v)); return Err(ParseError(numbered_from(&cc))); } }
            if let Some(fields)=c.child("fields"){ for f in fields.children_named("field"){ validate_field(f,&rctx)?; } }
        } else if c.name=="cluster"{
            let name=c.child_text("name");
            if name.is_none(){ let mut cc=ctx.to_vec(); cc.push(format!("Parsing unknown cluster at {}:{}", c.line,c.col)); cc.push("Expected a `<name>` tag, found none".into()); return Err(ParseError(numbered_from(&cc))); }
            let clname=name.unwrap();
            validate_dim(c,"cluster",&clname,ctx)?;
            if c.child("addressOffset").is_none(){ let mut cc=ctx.to_vec(); cc.push(format!("Parsing cluster `{}` at {}:{}", clname,c.line,c.col)); cc.push("Expected a `<addressOffset>` tag, found none".into()); return Err(ParseError(numbered_from(&cc))); }
            let mut cctx=ctx.to_vec(); cctx.push(format!("In cluster `{}`", clname));
            // cluster children are direct register/cluster elements; wrap in a fake Xml with same children
            let fake=Xml{name:"cluster".into(), attrs:Default::default(), children:c.children.clone(), text:String::new(), line:c.line, col:c.col};
            validate_block(&fake,&cctx)?;
        }
    }
    Ok(())
}
pub fn validate_svd(xml:&Xml)->Result<(),ParseError>{
    let devname=xml.child_text("name").unwrap_or_default();
    let base_ctx=vec![format!("In device `{}`", devname)];
    if let Some(per)=xml.child("peripherals"){
        for p in per.children_named("peripheral"){
            let pname=p.child_text("name");
            if pname.is_none(){ let mut c=base_ctx.clone(); c.push(format!("Parsing unknown peripheral at {}:{}", p.line,p.col)); c.push("Expected a `<name>` tag, found none".into()); return Err(ParseError(numbered_from(&c))); }
            let pname=pname.unwrap();
            validate_dim(p,"peripheral",&pname,&base_ctx)?;
            if p.child("baseAddress").is_none(){ let mut c=base_ctx.clone(); c.push(format!("Parsing peripheral `{}` at {}:{}", pname,p.line,p.col)); c.push("Expected a `<baseAddress>` tag, found none".into()); return Err(ParseError(numbered_from(&c))); }
            let mut pctx=base_ctx.clone(); pctx.push(format!("In peripheral `{}`", pname));
            if let Some(regs)=p.child("registers"){ validate_block(regs,&pctx)?; }
        }
    }
    Ok(())
}
