use serde_json::Value as J;
use crate::model::*;

fn get<'a>(o:&'a J, keys:&[&str])->Option<&'a J>{ for k in keys{ if let Some(v)=o.get(*k){ return Some(v); } } None }
fn gs(o:&J, keys:&[&str])->Option<String>{ get(o,keys).and_then(|v| if let J::String(s)=v{Some(s.clone())} else if v.is_number(){Some(v.to_string())} else {None}) }
fn gu(o:&J, keys:&[&str])->Option<u64>{ get(o,keys).and_then(|v| if let J::Number(n)=v{n.as_u64().or_else(|| n.as_i64().map(|i| i as u64))} else if let J::String(s)=v{parse_int(s).ok()} else {None}) }
fn gb(o:&J, keys:&[&str])->bool{ get(o,keys).map(|v| if let J::Bool(b)=v{*b}else if let J::String(s)=v{parse_bool(s)}else{false}).unwrap_or(false) }
fn props(o:&J)->Props{
    let mut p=Props::default();
    let src=get(o,&["properties"]).unwrap_or(o);
    if let Some(v)=gu(src,&["size"]){p.size=Some(v as u32);}
    if let Some(v)=gs(src,&["access"]){p.access=Access::parse(&v);}
    if let Some(v)=gu(src,&["resetValue","reset_value"]){p.reset_value=Some(v);}
    if let Some(v)=gu(src,&["resetMask","reset_mask"]){p.reset_mask=Some(v);}
    p
}
fn dim(o:&J)->Option<Dim>{ let d=gu(o,&["dim"])?; Some(Dim{dim:d as u32, increment:gu(o,&["dimIncrement","dim_increment"]).unwrap_or(0), index:gs(o,&["dimIndex","dim_index"]), name_index:gs(o,&["dimNameIndex"])}) }
fn enum_sets(o:&J)->Vec<EnumSet>{
    let mut out=vec![]; let Some(arr)=get(o,&["enumeratedValues","enumerated_values"]).and_then(|v| v.as_array()) else {return out};
    for e in arr {
        let mut vals=vec![];
        if let Some(vs)=get(e,&["values","enumeratedValue","enumeratedValues","enumerated_value"]).and_then(|v| v.as_array()){
            for v in vs{ vals.push(EnumValue{name:gs(v,&["name"]).unwrap_or_default(), description:gs(v,&["description"]), value:gu(v,&["value"]).unwrap_or(0), is_default:gb(v,&["isDefault","is_default"])}); }
        }
        out.push(EnumSet{name:gs(e,&["name"]), description:gs(e,&["description"]), usage:gs(e,&["usage"]).unwrap_or_else(||"read-write".into()), values:vals, derived_from:gs(e,&["derivedFrom","derived_from"]), header_enum_name:gs(e,&["headerEnumName"])});
    } out
}
fn field(o:&J)->Field{
    let (mut off, mut wid)=(gu(o,&["bitOffset","bit_offset"]).unwrap_or(0) as u32, gu(o,&["bitWidth","bit_width"]).unwrap_or(1) as u32);
    if let Some(br)=gs(o,&["bitRange","bit_range"]){ let t=br.trim().trim_matches(|c| c=='['||c==']'); if let Some((a,b))=t.split_once(':'){ let msb=a.trim().parse::<u32>().unwrap_or(0); let lsb=b.trim().parse::<u32>().unwrap_or(0); off=lsb; wid=msb-lsb+1; } }
    if let Some(v)=gu(o,&["lsb"]){off=v as u32;} if let Some(v)=gu(o,&["msb"]){wid=(v as u32)-off+1;}
    Field{name:gs(o,&["name"]).unwrap_or_default(), description:gs(o,&["description"]), bit_offset:off, bit_width:wid, access:gs(o,&["access"]).and_then(|s| Access::parse(&s)), enums:enum_sets(o), derived_from:gs(o,&["derivedFrom","derived_from"]), dim:dim(o), modified_write_values:gs(o,&["modifiedWriteValues","modified_write_values"]).and_then(|s| Mwv::parse(&s)), read_action:gs(o,&["readAction","read_action"]).and_then(|s| ReadAction::parse(&s)), write_constraint_range:None}
}
fn register(o:&J)->Register{
    let fields=if let Some(fs)=get(o,&["fields"]).and_then(|v| v.as_array()){ fs.iter().map(field).collect()} else {vec![]};
    Register{fields_present:o.get("fields").is_some(), name:gs(o,&["name"]).unwrap_or_default(), display_name:gs(o,&["displayName"]), description:gs(o,&["description"]), address_offset:gu(o,&["addressOffset","address_offset"]).unwrap_or(0), props:props(o), fields, derived_from:gs(o,&["derivedFrom","derived_from"]), dim:dim(o), alternate_group:gs(o,&["alternateGroup","alternate_group"]), alternate_register:gs(o,&["alternateRegister"]), modifier:gs(o,&["modifier"])}
}
fn block_elem(v:&J)->Option<BlockElem>{
    if let Some(r)=v.get("register"){ return Some(BlockElem::Register(register(r))); }
    if let Some(c)=v.get("cluster"){ return Some(BlockElem::Cluster(cluster(c))); }
    // plain object fallback
    if v.get("addressOffset").is_some() || v.get("address_offset").is_some(){ 
        // cluster plain has registers/children
        if v.get("registers").is_some() && v.get("fields").is_none(){ return Some(BlockElem::Cluster(cluster(v))); }
