#[derive(Clone)]
struct State { global: u8, modules: Vec<(String,u8)> }
fn state()->&'static Mutex<State>{ static S: OnceLock<Mutex<State>>=OnceLock::new(); S.get_or_init(|| Mutex::new(State{global:3, modules:vec![]})) }
fn parse_level(s:&str)->Option<u8>{ match s.to_ascii_lowercase().as_str(){ "off"=>Some(0),"error"=>Some(1),"warn"=>Some(2),"info"=>Some(3),"debug"=>Some(4),"trace"=>Some(5), _=>None } }
pub fn set_level_from_str(s:&str){ let mut st=state().lock().unwrap(); st.global=parse_level(s).unwrap_or(3); st.modules.clear(); }
pub fn init_from_env(){
