    let mut global:Option<u8>=None; let mut modules=vec![];
    for part in v.split(','){
        let part=part.trim(); if part.is_empty(){ continue; }
        if let Some((target,lvl))=part.split_once('='){
            let lvl_trim=lvl.trim();
            // strip regex filter after /
            let lvl_str=lvl_trim.split('/').next().unwrap_or("");
            if target.trim().is_empty(){ global=Some(parse_level(lvl_str).unwrap_or(5)); }
            else { modules.push((target.trim().to_string(), if lvl_str.is_empty(){5}else{parse_level(lvl_str).unwrap_or(5)})); }
        } else if let Some(l)=parse_level(part){ global=Some(l); }
        else {
