    // If env var is present but empty, env_logger likely defaults? state: if v empty, global above modules empty => unwrap gives 3? Actually we set global None and modules empty => 3 in code above (since modules empty)
    if v.trim().is_empty(){ st.global=3; }
}
pub fn level_for(target:&str)->u8{
    let st=state().lock().unwrap(); let mut best:Option<(usize,u8)>=None;
    for (m,l) in &st.modules { if target==m || target.starts_with(&format!("{}::",m)){ if best.map(|(len,_)| m.len()>=len).unwrap_or(true){ best=Some((m.len(),*l)); } } }
    if let Some((_,l))=best { l } else { st.global }
}
pub fn enabled_for(l:u8,target:&str)->bool{ l<=level_for(target) && level_for(target)!=0 }
