    let mut lines=msg.lines();
    if let Some(first)=lines.next(){ eprintln!("[{:<5} {}] {}", name, target, first); } else { eprintln!("[{:<5} {}] ", name, target); }
    for line in lines { eprintln!("    {}", line); }
}
pub fn info(target:&str,msg:&str){ log_msg(3,target,msg); }
