pub fn debug(target:&str,msg:&str){ log_msg(4,target,msg); }
pub fn trace(target:&str,msg:&str){ log_msg(5,target,msg); }
pub fn error(msg:&str){ log_msg(1,"svd2rust",msg); }
pub fn err_with_context(context:&str, cause:&str){
    let mut m=String::new(); m.push_str(context); m.push_str("\n\nCaused by:\n");
    for (i,line) in cause.lines().enumerate(){ if i>0 { m.push('\n'); } m.push_str("    "); m.push_str(line); }
    error(&m);
}
